INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'A strength training app: it generates a science-backed program for your goals and equipment, gives an exact weight and rep target for every set based on your results, and has 795 exercise videos and detailed progress charts.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Alpha Progression helps you build muscle and strength with a plan made for you. The plan generator takes into account your goals, equipment, training frequency and duration and builds a science-backed program from 795 exercises, whether Push Pull Legs, Upper Lower, Full Body or another split that fits your week. You can customize anything and prioritize the muscles you want to focus on. For every set the algorithm gives a precise weight, rep count and intensity target based on what you actually lifted, so training is challenging but not overreaching and you avoid plateaus. The exercise library is filmed by certified trainers in a real gym, covering setup, execution and common mistakes. Charts show progress for exercises, muscles and body measurements. There are plate and warmup calculators, multiple gyms, reps in reserve tracking and deloads.', 'manual' FROM DUAL WHERE @new = 1;
