SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'arvo.guru' OR LOWER(`name`) = LOWER('Arvo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Arvo', NULL, 'https://arvo.guru', NULL, NULL, 'AI-тренер для тих, хто займається в залі: підлаштовує кожен підхід у реальному часі з урахуванням втоми, підказує вагу на наступний підхід і реалізує відомі методики бодібілдингу. Є безкоштовний план і режим для персональних тренерів.', 'An AI coach for gym lifters: it adjusts every set in real time based on fatigue, suggests the weight for your next set and applies well-known bodybuilding methods. There is a free plan and a mode for personal trainers.', 'Arvo — застосунок-тренер для бодібілдингу й пауербілдингу, у якому кілька спеціалізованих AI-помічників підлаштовують тренування підхід за підходом. Він відповідає на запитання на кшталт «яку вагу брати далі», «чи не перетренувався я», «чи рівноцінна ця заміна вправи», враховує суб''єктивну складність підходів і відстежує обсяг навантаження. Реалізовано відомі методики, зокрема Kuba Method, Mentzer HIT і FST-7, а в базі понад 1300 вправ. Новачкам підійде простий режим, у якому застосунок вирішує все за вас; досвідченим атлетам і змагальникам — точна періодизація. Персональні тренери можуть вести клієнтів: AI пропонує плани, тренер їх перевіряє й стежить за прогресом через окрему панель. Є безкоштовний план без картки.', 'Arvo is a coaching app for bodybuilding and powerbuilding in which several specialized AI agents adapt your training set by set. It answers questions like what weight to use next, whether you are overtraining or whether an exercise swap is equivalent, takes into account how hard each set felt and tracks training volume. Well-known methods such as the Kuba Method, Mentzer HIT and FST-7 are built in, and the library has more than 1,300 exercises. Beginners can use a simple mode where the app decides everything; experienced lifters and competitors get precise periodization. Personal trainers can manage clients: the AI drafts plans, the coach reviews them and tracks progress from a dedicated dashboard. A free plan needs no credit card.', 'Підлаштування кожного підходу в реальному часі
Підказки щодо ваги й заміни вправ
Методики Kuba, Mentzer HIT, FST-7
Понад 1300 вправ
Простий режим для новачків
Відстеження обсягу навантаження
Панель для персональних тренерів і їхніх клієнтів', 'Real-time adjustment of every set
Advice on weights and exercise swaps
Kuba, Mentzer HIT and FST-7 methods
1,300+ exercises
Simple mode for beginners
Training volume tracking
Dashboard for personal trainers and their clients', 'Люди, які тренуються в залі — від новачків до змагальних бодібілдерів, а також персональні тренери.', 'Gym-goers from beginners to competitive bodybuilders, as well as personal trainers.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
