SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'centr.com' OR LOWER(`name`) = LOWER('Centr'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Centr', NULL, 'https://centr.com', NULL, NULL, 'Система для силових тренувань удома: обладнання й застосунок Centr Coach з тренуваннями, підібраними під ваше обладнання, рівень і цілі — сила, витривалість, довголіття чи підготовка до змагань HYROX.', 'A home strength training system: equipment plus the Centr Coach app with workouts matched to your gear, level and goals, whether that''s strength, endurance, longevity or racing HYROX.', 'Centr поєднує домашнє обладнання й тренерський застосунок в одну систему. Застосунок Centr Coach пропонує тренування з супроводом, підібрані під ваш набір обладнання, рівень підготовки й цілі, і допомагає розвивати силу, функціональну форму й витривалість. Можна обрати фокус: підготовка до змагань HYROX із сертифікованими тренуваннями для кожної станції, тренування для довголіття з бережним навантаженням на суглоби, набір сили, базова підготовка для новачків або стабільний режим занять, що вписується у ваш тиждень. Окремо продається обладнання: домашні зали, ваги й грифи, кардіотренажери, лави й стійки, а також офіційне змагальне обладнання HYROX, зокрема для дитячих стартів HYROX Youngstars. Застосунок можна спробувати 7 днів безкоштовно.', 'Centr combines home equipment and a coaching app into one connected system. The Centr Coach app offers guided workouts tailored to your equipment setup, fitness level and goals, helping you build strength, conditioning and endurance. You pick a focus: race-day preparation for HYROX with certified, station-specific workouts, longevity training that protects your joints, building strength, a beginner foundation, or a consistent routine that fits your week. Equipment is sold separately, including home gyms, weights and bars, cardio machines, benches and racks, and Official Competition Equipment for HYROX, including for the HYROX Youngstars junior races. The app can be tried free for 7 days.', 'Застосунок Centr Coach з тренуваннями з супроводом
Програми під ваше обладнання, рівень і цілі
Підготовка до змагань HYROX
Програми для довголіття й набору сили
Обладнання для домашнього залу
7 днів безкоштовного доступу', 'Centr Coach app with guided workouts
Programs matched to your equipment, level and goals
HYROX race preparation
Longevity and strength programs
Home gym equipment
7 days of free access', 'Люди, які облаштовують домашній зал і хочуть тренуватися за структурованими програмами — від новачків до учасників HYROX.', 'People setting up a home gym who want structured programs, from beginners to HYROX athletes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
