INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Coachify combines a personal trainer, a workout log and a calorie counter in one app. The AI builds a workout plan around your goals, schedule and available equipment and nudges your weights and reps up at the right pace. The app remembers everything you lift, compares each set against your average and instantly shows your gains as a percentage. There is a weekly calendar with streaks, plus calories burned, minutes and total sets for each workout. During training, smart rest timers, 3D exercise visuals for correct form, past logs and alternative exercises help you know what to do next. The nutrition section shows calories, macros, steps and energy burned, and you can log a meal in seconds with a photo. The AI trainer answers questions about form, plans and nutrition around the clock.', 'manual' FROM DUAL WHERE @new = 1;
