-- FitnessAI — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fitnessai.com' OR LOWER(`name`) = LOWER('FitnessAI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'FitnessAI', NULL, 'https://fitnessai.com', NULL, NULL, 'AI-застосунок для силових тренувань: підбирає підходи, повторення й вагу на основі мільйонів реальних тренувань, поступово збільшує навантаження, підлаштовується під ваше обладнання й час та знижує інтенсивність, коли потрібне відновлення.', 'An AI strength training app: it picks sets, reps and weights based on millions of real workouts, applies progressive overload, adapts to your equipment and schedule, and eases off when you need recovery.', 'FitnessAI допомагає набирати м''язову масу й спалювати жир без здогадок. Застосунок складає силові тренування на основі мільйонів реальних тренувальних сесій і точно підказує, яку вагу брати, скільки підходів і повторень робити. Навантаження поступово збільшується в реальному часі, щоб прогрес не зупинявся і не настало перетренування, а функція адаптивного відновлення знижує інтенсивність, коли варто відпочити. Сесії тривають від 5 до 30 хвилин і підлаштовуються під ваш графік та обладнання, вправи легко замінити. Відеоінструкції й візуалізація м''язів допомагають виконувати вправи правильно. Застосунок відстежує зростання сили й зміни складу тіла, синхронізується з Apple Watch і пропонує тематичні челенджі з нагородами.', 'FitnessAI helps you build muscle and burn fat without guesswork. The app programs strength workouts based on millions of real training sessions and tells you exactly what weight to lift and how many sets and reps to do. Progressive overload adjusts in real time so results don''t stall and you avoid burning out, while adaptive recovery lowers intensity when you need to back off. Sessions last 5 to 30 minutes, adapt to your schedule and equipment, and exercises are easy to swap. Guided videos and muscle visuals keep your form correct. The app tracks strength gains and body composition, syncs with Apple Watch and runs structured challenges with rewards.', 'Підбір ваги, підходів і повторень штучним інтелектом
Поступове збільшення навантаження в реальному часі
