SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'future.co' OR LOWER(`name`) = LOWER('Future'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Future', NULL, 'https://future.co', NULL, NULL, 'Персональні тренування онлайн з живим тренером: фахівець складає програму під ваші цілі, перевіряє прогрес, тримає вас у тонусі й поступово коригує план. Вправи — з відео, голосовими підказками й порадами щодо техніки.', 'Online personal training with a real coach: an expert builds a program around your goals, checks your progress, keeps you accountable and refines the plan over time. Every exercise comes with video, voice cues and form guidance.', 'Future — сервіс персональних тренувань, де за кожним користувачем закріплений власний тренер. Тренер складає програму під ваші цілі, наприклад схуднення чи силу, спираючись на перевірені методики, регулярно виходить на зв''язок, стежить за прогресом і допомагає не збиватися з графіка. План легко підлаштувати під реальне життя: тренування можна переносити, змінювати дні й адаптувати без штрафів, а тренер з часом уточнює програму, щоб навантаження росло разом із вами. У застосунку є бібліотека вправ із відеодемонстраціями, голосовими підказками й поясненнями техніки. Нещодавно з''явився й ширший супровід здоров''я — харчування, сон тощо. Перший місяць коштує дешевше, а протягом 30 днів можна скасувати підписку з повним поверненням коштів.', 'Future is a personal training service where every member gets a dedicated coach. The coach builds a program around your goals, such as weight loss or strength, using proven methods, checks in regularly, monitors your progress and helps you stay consistent. The plan fits real life: you can move workouts, change days and adapt the plan without penalty, and the coach refines it over time so your training evolves with you. The app includes an exercise library with video demos, voice cues and form guidance. Broader health coaching covering nutrition, sleep and more was added recently. The first month is discounted, and you can cancel within 30 days for a full refund.', 'Персональний тренер для кожного користувача
Програма тренувань під ваші цілі
Регулярні перевірки прогресу й підтримка
Гнучке перенесення тренувань
Бібліотека вправ із відео й голосовими підказками
Поради щодо техніки виконання
Супровід щодо харчування й сну', 'A dedicated personal coach for every member
Training program built around your goals
Regular progress check-ins and accountability
Flexible rescheduling of workouts
Exercise library with video and voice cues
Form guidance for every movement
Coaching on nutrition and sleep', 'Люди, які хочуть тренуватися регулярно з особистим тренером онлайн — для схуднення, сили чи загальної форми.', 'People who want to train consistently with a personal coach online, for weight loss, strength or general fitness.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
