INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Gravl builds a personalized strength training plan around your goals, equipment and schedule; the plan is dialed in by AI and backed by real coaches. Every session is already planned: exercises, sets, reps and weights. You log a set with one tap because reps and weight are prefilled, and the rest timer starts. The app tracks every set and adjusts next week''s weights automatically, so there are no spreadsheets and no guessing. Every exercise has a clear how-to video. Gravl tracks muscle recovery, including through Apple Health, adapts workouts to the gym you are in and shows your growing Strength Score. You can message coaches in the app about app tips or workout advice. Getting started is free.', 'manual' FROM DUAL WHERE @new = 1;
