-- Peloton — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'onepeloton.com' OR LOWER(`name`) = LOWER('Peloton'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Peloton', NULL, 'https://onepeloton.com', NULL, NULL, 'Тренажери й застосунок для домашнього фітнесу: бігові доріжки, велотренажери й гребні тренажери з тисячами занять від інструкторів, а помічник Peloton IQ складає тижневий план під вашу ціль і підлаштовує його.', 'Equipment and an app for home fitness: treadmills, bikes and rowers with thousands of instructor-led classes, while the Peloton IQ assistant builds a weekly plan around your goal and adapts it.', 'Peloton поєднує домашні тренажери з великою бібліотекою занять. У лінійці є бігові доріжки Tread, велотренажери Bike і гребний тренажер Row. Функція Peloton IQ допомагає не гадати, що робити: ви обираєте ціль — більше сили, витривалості тощо — і отримуєте персональний тижневий план, який підлаштовується під ваш прогрес. Доступно понад 10 000 занять у більш ніж 15 видах тренувань — біг, ходьба, силові, йога, пілатес, велотренування, бокс, греблі — з інструкторами під будь-який настрій і рівень. Заняття побудовані навколо спільноти, яка тренується разом. Нове покоління доріжок — Tread Flex, Tread Vision і Tread+ Vision — дозволяє бігати, ходити й тренуватися у власному темпі.', 'Peloton combines home exercise equipment with a large class library. The lineup includes Tread treadmills, Bike exercise bikes and the Row rower. Peloton IQ takes away the guesswork: you choose a goal, such as more strength or endurance, and get a personalized weekly plan that adapts to your progress. More than 10,000 classes are available across over 15 workout types, including running, walking, strength, yoga, Pilates, cycling, boxing and rowing, with instructors for every mood and level. Classes are built around a community that shows up together. The new generation of treadmills, Tread Flex, Tread Vision and Tread+ Vision, lets you run, walk and train at your own pace.', 'Бігові доріжки, велотренажери й гребний тренажер
Персональний тижневий план від Peloton IQ
Понад 10 000 занять з інструкторами
Понад 15 видів тренувань
Біг, силові, йога, пілатес, бокс, велотренування
Тренування разом зі спільнотою', 'Treadmills, bikes and a rower
Personalized weekly plan from Peloton IQ
10,000+ instructor-led classes
15+ workout types
Running, strength, yoga, Pilates, boxing, cycling
Training together with the community', 'Люди, які хочуть регулярно тренуватися вдома з тренажерами й заняттями від інструкторів.', 'People who want to work out regularly at home with equipment and instructor-led classes.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
