-- Runna — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'runna.com' OR LOWER(`name`) = LOWER('Runna'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Runna', NULL, 'https://runna.com', NULL, NULL, 'Застосунок-тренер для бігу: складає персональний план під вашу дистанцію чи дату забігу — від швидшої п''ятірки до першого марафону, підлаштовується під ваші результати й синхронізується з годинниками Garmin, Apple Watch, Coros та Strava.', 'A running coach app: it builds a personal plan for your distance or race date, from a faster 5K to your first marathon, adapts to your results and syncs with Garmin, Apple Watch, Coros watches and Strava.', 'Runna допомагає бігунам будь-якого рівня тренуватися за персональним планом. Ви вказуєте свій рівень, цільову дистанцію чи дату забігу, скільки днів на тиждень готові бігати — і застосунок будує план під ваш графік, а калькулятор одразу оцінює можливий час на фініші. Плани створені досвідченими тренерами, містять поради щодо темпу й розкладу та підлаштовуються під ваші результати. Тренування можна виконувати й відстежувати з улюбленими пристроями — Apple Watch, Garmin, Fitbit, Coros — та синхронізувати зі Strava. Є аналітика прогресу, підтримка команди Runna, спільнота й знижки від партнерів. Перший тиждень безкоштовний, скасувати можна будь-коли.', 'Runna helps runners of any level train with a personal plan. You enter your level, target distance or race date and how many days a week you can run, and the app builds a plan around your schedule, while a calculator estimates your likely finish time. Plans are created by experienced coaches, include advice on pacing and scheduling, and adapt to your performance. You can run and track workouts with your favourite devices, including Apple Watch, Garmin, Fitbit and Coros, and sync with Strava. There are progress insights, support from the Runna team, a community and partner discounts. The first week is free and you can cancel anytime.', 'Персональні бігові плани під будь-яку дистанцію
Адаптація плану під ваші результати
Калькулятор очікуваного часу забігу
Поради тренерів щодо темпу й розкладу
Синхронізація з Apple Watch, Garmin, Fitbit, Coros
Підключення до Strava
Аналітика тренувань і прогресу', 'Personal running plans for any distance
Plan adapts to your performance
Estimated race time calculator
Coach advice on pacing and scheduling
Sync with Apple Watch, Garmin, Fitbit, Coros
Strava connection
Workout and progress insights', 'Бігуни будь-якого рівня — від тих, хто готується до першої п''ятірки, до марафонців.', 'Runners of every level, from people preparing for their first 5K to marathoners.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
