-- Strava — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'strava.com' OR LOWER(`name`) = LOWER('Strava'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Strava', NULL, 'https://strava.com', NULL, NULL, 'Застосунок і соцмережа для активних людей: записує біг, велопоїздки й походи з телефона чи GPS-годинника, показує швидкість, темп, дистанцію й порівняння з минулими спробами, а також допомагає планувати маршрути й тренуватися з друзями.', 'An app and social network for active people: it records runs, rides and hikes from your phone or GPS watch, shows speed, pace, distance and comparisons with past efforts, and helps you plan routes and train with friends.', 'Strava — застосунок і сайт для бігунів, велосипедистів, туристів і всіх, хто любить рухатися. Активність записується з телефона чи улюбленого GPS-пристрою, а після тренування доступна детальна карта й багато показників: швидкість, темп, дистанція, порівняння з вашими минулими спробами та показник відносного навантаження Relative Effort. У веб-версії є плани тренувань, планування маршрутів і докладний розбір активностей. Головна сила Strava — спільнота: стрічка з тренуваннями друзів, клуби, змагання на відрізках маршрутів, пошук нових маршрутів, забігів і партнерів для тренувань. Базове користування безкоштовне.', 'Strava is an app and website for runners, cyclists, hikers and anyone who loves to move. Activities are recorded with your phone or favourite GPS device, and afterwards you get a detailed map and plenty of metrics: speed, pace, distance, comparisons with your past attempts and the Relative Effort score. The web version adds training plans, route planning and in-depth activity breakdowns. Strava''s main strength is its community: a feed of friends'' workouts, clubs, segment competitions, and discovery of new routes, races and training partners. Basic use is free.', 'Запис бігу, велопоїздок і походів
Карта й детальні показники активності
Порівняння з минулими спробами
Показник навантаження Relative Effort
Плани тренувань і планування маршрутів
Стрічка друзів, клуби й змагання на відрізках
Робота з телефоном і GPS-пристроями', 'Recording runs, rides and hikes
Map and detailed activity metrics
Comparison with past efforts
Relative Effort training load score
Training plans and route planning
Friends feed, clubs and segment competitions
Works with phones and GPS devices', 'Бігуни, велосипедисти, туристи й усі активні люди, які хочуть відстежувати тренування й спілкуватися зі спільнотою.', 'Runners, cyclists, hikers and all active people who want to track workouts and connect with a community.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
