-- Sweat — Масовий фітнес і тренування
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sweat.com' OR LOWER(`name`) = LOWER('Sweat'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sweat', NULL, 'https://sweat.com', NULL, NULL, 'Фітнес-застосунок, створений жінками для жінок: понад 70 програм і тисячі тренувань для дому й залу під будь-яку ціль і рівень, понад 500 рецептів і відстеження прогресу. Перший тиждень — безкоштовно.', 'A fitness app designed by women, for women: 70+ programs and thousands of workouts for home and gym for any goal and level, 500+ recipes and progress tracking. The first week is free.', 'Sweat — фітнес-застосунок, створений жінками для жінок, який допомагає знайти план тренувань, що вписується у ваше життя. Незалежно від цілі, рівня підготовки чи способу життя ви обираєте одну з понад 70 програм і отримуєте тренера та план тренувань у телефоні. Доступні тисячі тренувань із варіантами для дому й залу, а якщо потрібного обладнання немає — є альтернативи. Програми можна змінювати й поєднувати, коли хочеться різноманіття. Окрім тренувань, у застосунку понад 500 рецептів. Прогрес відстежується, тож видно, наскільки ви просунулися — і у вдалі, і у важкі дні. Сервіс підходить і новачкам. Перший тиждень безкоштовний, підписку можна скасувати будь-коли.', 'Sweat is a fitness app designed by women, for women, that helps you find a workout plan that fits your life. Whatever your goal, level or lifestyle, you pick one of more than 70 programs and get a trainer and a plan in your pocket. Thousands of workouts are available with home and gym options, and there are alternatives if you don''t have the right equipment. You can switch and combine programs when you want variety. Beyond workouts, the app has more than 500 recipes. Progress tracking shows how far you''ve come, on your best days and your toughest. Sweat is suitable for beginners. The first week is free and you can cancel anytime.', 'Понад 70 програм тренувань
Тисячі тренувань для дому й залу
Альтернативи за відсутності обладнання
Можливість змінювати й поєднувати програми
Понад 500 рецептів
Відстеження прогресу
Підходить для новачок', '70+ training programs
Thousands of home and gym workouts
Alternatives when you lack equipment
Switch and combine programs
