INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Sweat is a fitness app designed by women, for women, that helps you find a workout plan that fits your life. Whatever your goal, level or lifestyle, you pick one of more than 70 programs and get a trainer and a plan in your pocket. Thousands of workouts are available with home and gym options, and there are alternatives if you don''t have the right equipment. You can switch and combine programs when you want variety. Beyond workouts, the app has more than 500 recipes. Progress tracking shows how far you''ve come, on your best days and your toughest. Sweat is suitable for beginners. The first week is free and you can cancel anytime.', 'manual' FROM DUAL WHERE @new = 1;
