SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tonal.com' OR LOWER(`name`) = LOWER('Tonal'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Tonal', NULL, 'https://tonal.com', NULL, NULL, 'Розумний домашній тренажер для силових тренувань: сам визначає вашу силу й підбирає опір для кожного повторення, веде науково обґрунтовані тренування з підказками в реальному часі та автоматично відстежує прогрес.', 'A smart home gym for strength training: it learns your strength and sets the resistance for every rep, runs science-backed workouts with real-time guidance and tracks your progress automatically.', 'Tonal замінює звичайне обладнання залу компактним розумним тренажером, який дає вдома досвід персонального тренера й повноцінного залу. Система вивчає вашу силу й встановлює оптимальний опір для кожного повторення, підвищуючи його з кроком до одного фунта, коли ви стаєте сильнішими. Тренування побудовані на наукових підходах і супроводжуються підказками в реальному часі, щоб займатися безпечно й з максимальною віддачею. Прогрес відстежується автоматично, а аналітика показує, як росте ваша сила. Є просунуті режими, як-от дроп-сети з автоматичною зміною ваги без перевішування дисків. Одне членство дає необмежену кількість облікових записів для всієї родини. Покупка тренажера передбачає 12-місячне членство; є також оренда з першим місяцем безкоштовно.', 'Tonal replaces standard gym equipment with a compact smart machine that brings the expertise of a personal trainer and a full gym into your home. The system learns your strength and sets the optimal resistance for every rep, increasing it in steps as small as one pound as you get stronger. Workouts are science-backed and come with real-time guidance so you train safely and get the most from every effort. Progress is tracked automatically, and insights show how your strength is growing. Advanced lifting modes include drop sets that adjust the weight automatically, so you never re-rack. One membership covers unlimited accounts for the whole household. Buying Tonal requires a 12-month membership; Tonal Rent lets you try it with the first month free.', 'Автоматичний підбір опору під вашу силу
Тренування з підказками в реальному часі
Автоматичне відстеження прогресу й сили
Просунуті режими, зокрема дроп-сети
Необмежена кількість профілів у родині
Оренда тренажера з першим місяцем безкоштовно', 'Automatic resistance based on your strength
Workouts with real-time guidance
Automatic progress and strength tracking
Advanced modes such as drop sets
Unlimited household accounts
Rental with the first month free', 'Люди, які хочуть займатися силовими тренуваннями вдома з розумним тренажером замість залу — від новачків до досвідчених.', 'People who want to strength train at home with a smart machine instead of a gym, from beginners to experienced lifters.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
