SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zwift.com' OR LOWER(`name`) = LOWER('Zwift'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Zwift', NULL, 'https://zwift.com', NULL, NULL, 'Застосунок для велотренувань удома: віртуальні маршрути з підйомами й рівнинами, тисячі тренувань, персональні плани, що підлаштовуються під прогрес, групові заїзди цілодобово та перегони для будь-якого рівня.', 'An indoor cycling app: virtual routes with climbs and flats, thousands of workouts, personalized plans that adapt to your progress, group rides around the clock and racing for every level.', 'Zwift робить тренування на велотренажері вдома цікавими. Ви під''єднуєте смарт-тренажер або фірмовий смарт-велосипед Zwift Ride і катаєтеся віртуальними маршрутами — від гірських підйомів до рівнин уздовж узбережжя. У застосунку тисячі тренувань під будь-який графік, персональні плани, які підлаштовуються під ваш прогрес, групові заїзди 24/7 цілий рік, фірмові тури й події, а також перегони — від подій для новачків до національних чемпіонатів. За активність відкриваються нові рівні й нагороди, а тренуватися можна разом із великою світовою спільнотою. Доступна місячна або річна підписка; новим користувачам — пробний період.', 'Zwift makes indoor training on a bike trainer fun. You connect a smart trainer or the Zwift Ride smart bike and ride virtual routes, from alpine climbs to beachside flats. The app offers thousands of workouts to fit any schedule, personalized training plans that adapt to your progress, group rides 24/7 all year, flagship tours and events, and racing from beginner events to national championships. Riding unlocks new levels and in-game rewards, and you train alongside a large global community. Monthly or annual memberships are available, with a trial for new members.', 'Віртуальні велосипедні маршрути
Тисячі структурованих тренувань
Персональні плани з адаптацією під прогрес
Групові заїзди цілодобово
Перегони для будь-якого рівня
Рівні й нагороди за активність
Робота зі смарт-тренажерами й Zwift Ride', 'Virtual cycling routes
Thousands of structured workouts
Personalized plans that adapt to progress
Group rides around the clock
Racing for every level
Levels and rewards for activity
Works with smart trainers and Zwift Ride', 'Велосипедисти й усі, хто тренується на велотренажері вдома — від новачків до професіоналів.', 'Cyclists and anyone who trains on an indoor bike at home, from beginners to pros.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
