-- 360Player — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = '360player.com' OR LOWER(`name`) = LOWER('360Player'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT '360Player', NULL, 'https://360player.com', NULL, NULL, 'Програма для керування спортивним клубом: реєстрація, членство й оплати, спілкування з гравцями й батьками, тренування й розвиток гравців в одному місці — без перемикання між різними сервісами й рутинної адмінроботи.', 'Sports club management software: registrations, memberships and payments, communication with players and parents, training and player development in one place, without switching between tools or repetitive admin.', '360Player — платформа для керування спортивними клубами, яка збирає всі робочі інструменти в одному місці, щоб не перемикатися між сервісами й не витрачати час на повторювану адміністративну роботу. Клуби ведуть реєстрацію й членство, приймають оплати з конкурентними комісіями, спілкуються з гравцями, тренерами й батьками, організовують тренування й стежать за розвитком гравців. Рішення підлаштовується під структуру й цілі конкретного клубу і підходить організаціям будь-якого розміру — від аматорських клубів до елітних академій. Команда 360Player допомагає перенести членів і команди з попередньої системи та супроводжує налаштування, тож більшість клубів запускаються за кілька днів. Ціна залежить від кількості членів і модулів, тому формується індивідуально після розмови з відділом продажів.', '360Player is a sports club management platform that brings all working tools into one place, so clubs don''t switch between services or lose time on repetitive admin. Clubs handle registrations and memberships, take payments with competitive fees, communicate with players, coaches and parents, organize training and follow player development. The solution adapts to each club''s structure and goals and suits organizations of every size, from grassroots clubs to elite academies. The 360Player team migrates members and teams from the previous system and guides setup, so most clubs are up and running in days. Pricing depends on membership size and modules used, so it is quoted individually after a conversation with sales.', 'Реєстрація й керування членством
Прийом оплат із низькими комісіями
Спілкування з гравцями, тренерами й батьками
Організація тренувань
Розвиток гравців
Допомога з переходом з іншої системи', 'Registrations and membership management
Payments with low fees
Communication with players, coaches and parents
Training organization
Player development
Help migrating from another system', 'Спортивні клуби й академії будь-якого рівня, їхні адміністратори й тренери.', 'Sports clubs and academies of every level, their administrators and coaches.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
