INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ABC Trainerize', NULL, 'https://trainerize.com', NULL, NULL, 'Програма для персональних тренерів, студій і фітнес-клубів: конструктор тренувань із підтримкою AI, програми харчування й звичок, відеокоучинг, спілкування з клієнтами, розклад, оплати й брендовані застосунки.', 'Software for personal trainers, studios and fitness clubs: an AI-assisted workout builder, nutrition and habit programs, video coaching, client messaging, scheduling, payments and custom branded apps.', 'ABC Trainerize допомагає фітнес-професіоналам складати індивідуальні програми, стежити за прогресом клієнтів і розвивати свій бізнес. Платформою користуються незалежні тренери, нутриціологи, лайфстайл- і велнес-коучі, студії, зали, фітнес-клуби та корпоративні програми благополуччя. Вона підтримує онлайн, очні, гібридні й групові тренування, а також коучинг із харчування. Для роботи з клієнтами є конструктор тренувань з підтримкою AI, модулі харчування, звичок і мотивації. Для спілкування — повідомлення, спільнота й відеокоучинг. Для керування бізнесом — розклад, оплати, ведення клієнтів і команд, інтеграції. Для зростання — аналітика FitMetrics, інструменти маркетингу й застосунки під власним брендом. Є навчальна академія з бізнес-курсами й майстер-класами.', 'ABC Trainerize helps fitness professionals deliver customized programs, track client progress and grow their business. It is used by independent coaches, nutrition, lifestyle and wellness coaches, studios, gyms, fitness clubs and corporate wellness programs. It supports online, in-person, hybrid and group training as well as nutrition coaching. For coaching there is an AI-assisted workout builder and modules for nutrition, habits and motivation. For engagement there is messaging, community and video coaching. For running the business there is scheduling, payments, client and team management, and integrations. For growth there are FitMetrics analytics, marketing tools and custom branded apps. An academy offers business courses and masterclasses.', 'Конструктор тренувань із підтримкою AI
Програми харчування й звичок
Відеокоучинг і спілкування з клієнтами
Онлайн, очні, гібридні й групові тренування
Розклад і прийом оплат
Аналітика FitMetrics і маркетинг
Застосунки під власним брендом', 'AI-assisted workout builder
Nutrition and habit programs
Video coaching and client messaging
Online, in-person, hybrid and group training
Scheduling and payments
FitMetrics analytics and marketing
Custom branded apps', 'Персональні тренери, нутриціологи, коучі, студії, зали й фітнес-клуби.', 'Personal trainers, nutrition coaches, wellness coaches, studios, gyms and fitness clubs.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
