-- BridgeAthletic — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bridgeathletic.com' OR LOWER(`name`) = LOWER('BridgeAthletic'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'BridgeAthletic', NULL, 'https://bridgeathletic.com', NULL, NULL, 'Програма для силової й фізичної підготовки: тренери створюють індивідуальні програми, тренують спортсменів очно чи дистанційно, порівнюють заплановане й фактичне навантаження та відстежують результати спортсменів.', 'Strength and conditioning software: coaches design custom programs, train athletes in person or remotely, compare prescribed and actual workloads and track athlete performance.', 'BridgeAthletic — програмне забезпечення для силової й фізичної підготовки, яке допомагає тренерам створювати індивідуальні програми, тренувати очно чи дистанційно та відстежувати результати. Рішення розраховані на професійні клуби, університетські спортивні відділи, центри підготовки, національні збірні, персональних і функціональних тренерів, зали, студії, силові структури, а також шкільні й молодіжні клуби. Платформа дозволяє швидко перетворювати знання тренера на ефективні програми з керуванням вагою, обсягом і інтенсивністю. Вона допомагає підтримувати зв''язок із віддаленими спортсменами й залучати кількох фахівців до програми одного спортсмена. Звіти «заплановано проти фактично виконано» показують, наскільки точно тренер прогнозує навантаження і чи не перевантажує клієнтів.', 'BridgeAthletic is strength and conditioning software that helps coaches design custom programs, train in person or remotely and track performance. It serves pro sports organizations, collegiate departments, performance centers, national teams, personal and functional trainers, gyms, studios, tactical organizations, high schools and youth clubs. The platform lets coaches quickly turn their knowledge into effective programs with control over load, volume and intensity. It helps stay in touch with remote athletes and involve multiple practitioners in one athlete''s program. Prescribed versus actual reporting shows how accurately a coach predicts workloads and whether clients are over- or under-prescribed.', 'Створення індивідуальних тренувальних програм
Керування вагою, обсягом і інтенсивністю
Очні й дистанційні тренування
Спільна робота кількох фахівців
Звіти заплановане проти фактичного навантаження
Відстеження результатів спортсменів', 'Custom training program design
Control of load, volume and intensity
In-person and remote training
Collaboration across practitioners
Prescribed vs actual workload reports
Athlete performance tracking', 'Тренери з фізпідготовки професійних і університетських команд, національних збірних, персональні тренери, зали й силові структури.', 'Strength coaches of pro and college teams and national teams, personal trainers, gyms and tactical organizations.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
