SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coachcatalyst.com' OR LOWER(`name`) = LOWER('Coach Catalyst'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Coach Catalyst', NULL, 'https://coachcatalyst.com', NULL, NULL, 'Платформа для онлайн-коучингу: конструктор тренувань, перевірка техніки клієнтів, трекер звичок і завдань, форми, освітні уроки, відео- й аудіонотатки, звіти, інтеграція з носимими пристроями й застосунки для тренера й клієнта.', 'An online coaching platform: a workout builder, client form checks, habit and task tracking, forms, education lessons, video and audio notes, reports, wearable integrations and apps for coach and client.', 'Coach Catalyst — універсальна платформа для онлайн-коучингу, яка замінює кілька розрізнених інструментів одним застосунком. Тренер веде всю взаємодію з клієнтами в одному місці: розклад, спілкування, відстеження прогресу. Можна створювати власні програми або змінювати готові, перевіряти техніку виконання вправ, вести трекер звичок і завдань з нагадуваннями, створювати форми й керувати освітнім контентом — доступно понад 1000 уроків, які можна змінювати, і понад 30 готових челенджів. Є відео- та аудіонотатки, звіти й візуалізація даних, інтеграції з носимими пристроями й обліком макроелементів, портал для клієнтів на вимогу та спільнота. Старший план додає необмежену кількість тренерів і спільнот, AI-помічника Habby й пріоритетну підтримку. Клієнти приєднуються безкоштовно, підписка помісячна без довгих контрактів, є 14-денний безкоштовний період.', 'Coach Catalyst is an all-in-one online coaching platform that replaces several separate tools with one app. Coaches manage every client interaction in one place: scheduling, communication and progress tracking. You can create your own programs or modify existing ones, review exercise form, run habit and task tracking with reminders, build forms and manage education content, with more than 1,000 modifiable lessons and over 30 done-for-you challenges. There are video and audio notes, reports and data visualization, wearable and macro integrations, an on-demand client portal and a community. The higher plan adds unlimited coaches and communities, the Habby AI assistant and priority support. Clients join for free, subscriptions are month-to-month with no long contracts, and there is a 14-day free trial.', 'Конструктор тренувань і перевірка техніки
Трекер звичок і завдань
Понад 1000 уроків і 30 готових челенджів
Відео- й аудіонотатки
Звіти й візуалізація даних
Інтеграція з носимими пристроями
AI-помічник Habby', 'Workout builder and form checks
Habit and task tracking
1,000+ lessons and 30 ready challenges
Video and audio notes
Reports and data visualization
Wearable integrations
Habby AI assistant', 'Онлайн-тренери й коучі зі здоров''я та фітнесу, які ведуть до кількох сотень клієнтів.', 'Online fitness and health coaches managing up to several hundred clients.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
