-- CoachNow — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coachnow.com' OR LOWER(`name`) = LOWER('CoachNow'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'CoachNow', NULL, 'https://coachnow.com', NULL, NULL, 'Застосунок для тренерів і спортсменів: відеоаналіз з уповільненням, відстеженням за допомогою AI й анотаціями, приватне спілкування, хмарна бібліотека вправ і планів, автоматичні розсилки, розклад і оплати занять.', 'An app for coaches and athletes: video analysis with slow motion, AI-enhanced tracking and annotations, private messaging, a cloud library of drills and plans, automated messaging, plus session scheduling and payments.', 'CoachNow — універсальна платформа для дистанційного й очного тренування, яка допомагає тренерам і спортсменам бути на зв''язку до, під час і між заняттями. Записуйте й надсилайте відео, фото, текст, аудіо та файли просто під час сесії. Вбудований набір для відеоаналізу має уповільнене відтворення, відстеження руху з підтримкою AI, інструменти анотацій і запис з кількох камер, тож відгук стає чітким і приватним. Усе спілкування й матеріали зібрані в одному місці замість пошти й месенджерів. Вправи, моделі техніки й тренувальні плани зберігаються в хмарній бібліотеці для повторного використання. Можна писати одному чи тисячам спортсменів одночасно, планувати публікації наперед, а на старшому тарифі — вести розклад, календар закладу й приймати оплати. Платформу використовують у понад 60 видах спорту. Будь-який план можна спробувати 7 днів безкоштовно.', 'CoachNow is an all-in-one platform for remote and in-person coaching that keeps coaches and athletes connected before, during and between sessions. You can record and share videos, images, text, audio and files right in a session. The built-in video analysis suite offers slow motion, AI-enhanced tracking, annotation tools and multi-camera capture, so feedback is clear and private. All communication and content live in one place instead of email and texts. Drills, technique models and practice plans are stored in a cloud library for reuse. You can message one or thousands of athletes at once, schedule posts in advance and, on the top plan, manage scheduling, a facility calendar and payments. The platform is used across more than 60 sports. Any plan can be tried free for 7 days.', 'Відеоаналіз з уповільненням і анотаціями
Відстеження руху з підтримкою AI
Запис із кількох камер
Приватне спілкування з кожним спортсменом
Хмарна бібліотека вправ і планів
Масові й заплановані розсилки
Розклад занять і прийом оплат', 'Video analysis with slow motion and annotations
AI-enhanced motion tracking
Multi-camera capture
Private messaging with each athlete
Cloud library of drills and plans
Bulk and scheduled messaging
Session scheduling and payments', 'Тренери, академії, табори й спортсмени в будь-якому виді спорту, а також батьки юних спортсменів.', 'Coaches, academies, camps and athletes in any sport, as well as parents of young athletes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
