INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'CoachNow is an all-in-one platform for remote and in-person coaching that keeps coaches and athletes connected before, during and between sessions. You can record and share videos, images, text, audio and files right in a session. The built-in video analysis suite offers slow motion, AI-enhanced tracking, annotation tools and multi-camera capture, so feedback is clear and private. All communication and content live in one place instead of email and texts. Drills, technique models and practice plans are stored in a cloud library for reuse. You can message one or thousands of athletes at once, schedule posts in advance and, on the top plan, manage scheduling, a facility calendar and payments. The platform is used across more than 60 sports. Any plan can be tried free for 7 days.', 'manual' FROM DUAL WHERE @new = 1;
