INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Exercise.com', NULL, 'https://exercise.com', NULL, NULL, 'Програма для фітнес-бізнесу: бронювання й відмітки, керування членами клубу й персоналом, конструктор і журнал тренувань, звіти, маркетинг, онлайн-продаж програм, трансляції, оплати й брендовані застосунки для залів і тренерів.', 'Software for fitness businesses: booking and check-ins, member and staff management, a workout builder and logger, reports, marketing, online program sales, livestreaming, payments and branded apps for gyms and trainers.', 'Exercise.com — універсальна платформа для управління й розвитку фітнес-бізнесу. Нею користуються зали, кросфіт-бокси, персональні тренери, фітнес-блогери, бутікові студії, центри спортивної підготовки, спортивні команди, тренери з фізпідготовки, фізіотерапевти, студії йоги, пілатесу й бойових мистецтв, корпоративні програми благополуччя. Бізнес-модуль охоплює відмітки, бронювання, керування членами клубу й персоналом, звіти, роботу в кількох локаціях, віддалений доступ до дверей, електронні договори й автоматизації. Для тренувань є конструктор планів, журнал тренувань, тренування на екранах, бібліотека вправ, прогресії від максимуму, звіти про результати, таблиці лідерів, фото прогресу й облік звичок. Маркетинг включає CRM, ліди, email, SMS і пуш-повідомлення, воронки продажів і сайти. Онлайн можна продавати програми, проводити трансляції, групи й челенджі. Окремо — прийом оплат, магазин, комісії тренерів і брендовані застосунки. Доступна демонстрація.', 'Exercise.com is an all-in-one platform for running and growing a fitness business. It is used by gyms, CrossFit boxes, personal trainers, fitness influencers, boutique studios, sports performance centers, sports teams, strength coaches, physical therapists, yoga, Pilates and martial arts studios, and corporate wellness programs. The business module covers check-ins, booking, member and staff management, reports, multi-location support, remote door access, e-sign waivers and automations. For training there is a workout plan creator, a workout logger, TV workouts, an exercise library, rep max progressions, performance reporting, leaderboards, progress photos and habit tracking. Marketing includes CRM, leads, email, SMS and push notifications, sales funnels and websites. Online you can sell workout plans, livestream, run groups and challenges. Payments, e-commerce, trainer commissions and branded apps are included. Demos are available.', 'Бронювання, відмітки й керування членами клубу
Конструктор і журнал тренувань
Звіти про результати й таблиці лідерів
CRM, email, SMS і воронки продажів
Онлайн-продаж програм і трансляції
Прийом оплат і магазин
Брендовані застосунки', 'Booking, check-ins and member management
Workout builder and logger
Performance reports and leaderboards
CRM, email, SMS and sales funnels
Online program sales and livestreaming
Payment processing and e-commerce
Branded apps', 'Власники залів і студій, персональні тренери, спортивні команди й центри підготовки, фітнес-блогери.', 'Gym and studio owners, personal trainers, sports teams and performance centers, fitness influencers.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
