SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'finalsurge.com' OR LOWER(`name`) = LOWER('Final Surge'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Final Surge', NULL, 'https://finalsurge.com', NULL, NULL, 'Безкоштовний онлайн-журнал тренувань для бігунів, тріатлоністів, велосипедистів і плавців та платформа для їхніх тренерів: календар тренувань, синхронізація з Garmin Connect і Strava, плани від тренерів, конструктор тренувань і аналіз результатів.', 'A free online training log for runners, triathletes, cyclists and swimmers plus a platform for their coaches: a training calendar, sync with Garmin Connect and Strava, coach-made plans, a workout builder and performance analysis.', 'Final Surge допомагає спортсменам, тренерам, командам і клубам планувати, відстежувати й аналізувати тренування для короткострокових і довгострокових цілей. Спортсмени ведуть календар тренувань, автоматично синхронізують заплановані й виконані тренування з Garmin Connect, Strava, TrainerRoad та іншими сервісами, аналізують статистику самостійно або працюють із тренером. Без тренера можна купити плани від досвідчених фахівців. Для тренерів є зручне спілкування зі спортсменами, швидкий доступ до всіх підопічних, конструктор тренувань із власною бібліотекою та моніторинг результатів. Платформа підходить для бігових і тріатлонних клубів, тренувальних груп і магазинів. Для спортсменів сервіс безкоштовний, тренерські пакети платні; для шкіл і коледжів є знижки. Доступні веб-версія, iOS і Android.', 'Final Surge helps athletes, coaches, teams and clubs plan, track and analyze training for short- and long-term goals. Athletes keep a training calendar, auto-sync planned and completed workouts with Garmin Connect, Strava, TrainerRoad and more, and analyze their stats on their own or with a coach. Without a coach, they can buy plans from experienced coaches. Coaches get easy athlete communication, quick access to all athletes, a workout builder with a custom library and performance monitoring. The platform suits running and triathlon clubs, training groups and specialty stores. It is free for athletes, coach packages are paid, and high schools and colleges get discounts. It is available on the web, iOS and Android.', 'Календар і журнал тренувань
Синхронізація з Garmin Connect, Strava, TrainerRoad
Плани від досвідчених тренерів
Конструктор тренувань для тренерів
Моніторинг результатів спортсменів
Статистика й аналіз тренувань', 'Training calendar and log
Sync with Garmin Connect, Strava, TrainerRoad
Plans from experienced coaches
Workout builder for coaches
Athlete performance monitoring
Training stats and analysis', 'Бігуни, тріатлоністи, велосипедисти й плавці, їхні тренери, клуби й шкільні команди.', 'Runners, triathletes, cyclists and swimmers, their coaches, clubs and school teams.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
