SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'harbiz.io' OR LOWER(`name`) = LOWER('Harbiz'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Harbiz', NULL, 'https://harbiz.io', NULL, NULL, 'Програма для персональних тренерів, залів, студій йоги й пілатесу, фізіотерапевтів і нутриціологів: ведення клієнтів, видача програм тренувань і харчування, автоматичне відстеження, оплати, маркетинг і AI-помічник Harbiz AI.', 'Software for personal trainers, gyms, yoga and Pilates studios, physiotherapists and nutritionists: client management, workout and nutrition plans, automated tracking, payments, marketing and the Harbiz AI assistant.', 'Harbiz допомагає фітнес- і велнес-фахівцям організувати роботу, спілкуватися з клієнтами й приймати оплати в одному місці. Платформа підходить персональним тренерам, студіям йоги й пілатесу, фізіотерапевтам, нутриціологам і залам. Можна вести клієнтів, видавати їм плани тренувань і харчування, автоматизувати відстеження результатів і розвивати бізнес. Harbiz AI — помічник штучного інтелекту, створений спеціально для персональних тренерів, який автоматизує складання програм, тренувань і планів харчування. Доступні групи, панель бізнес-даних, експорт звітів, маркетингові інструменти Harbiz Marketing, власний застосунок для iOS і Android та спільнота професіоналів. Тарифи відрізняються кількістю клієнтів і рівнем підтримки. Є 14-денний безкоштовний період без картки, скасувати можна будь-коли.', 'Harbiz helps fitness and wellness professionals organize their work, communicate with clients and get paid in one place. It suits personal trainers, yoga and Pilates studios, physiotherapists, nutritionists and gyms. You can manage clients, deliver workout and nutrition plans, automate results tracking and grow your business. Harbiz AI is an assistant built specifically for personal trainers that automates programs, workouts and nutrition plans. There are groups, a business data dashboard, report exports, Harbiz Marketing tools, your own iOS and Android app and a professional community. Plans differ by number of clients and support level. There is a 14-day free trial with no credit card, and you can cancel anytime.', 'Ведення клієнтів і групи
Програми тренувань і харчування
AI-помічник Harbiz AI
Автоматичне відстеження результатів
Прийом оплат
Маркетингові інструменти й бізнес-аналітика
Власний застосунок для iOS і Android', 'Client management and groups
Workout and nutrition plans
Harbiz AI assistant
Automated results tracking
Payment processing
Marketing tools and business analytics
Your own iOS and Android app', 'Персональні тренери, студії йоги й пілатесу, фізіотерапевти, нутриціологи й зали.', 'Personal trainers, yoga and Pilates studios, physiotherapists, nutritionists and gyms.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
