SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kahunas.io' OR LOWER(`name`) = LOWER('Kahunas'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Kahunas', NULL, 'https://kahunas.io', NULL, NULL, 'Платформа для онлайн-тренерів, яка дає власний брендований застосунок у магазинах застосунків: клієнти записують харчування й тренування, проходять перевірки, бачать прогрес, отримують преміум-контент і спілкуються голосовими повідомленнями.', 'A platform for online coaches that gives you your own branded app in the app stores: clients log nutrition and workouts, complete check-ins, see progress, access premium content and send voice notes.', 'Kahunas — універсальна платформа для коучингу, яка замінює незручні сервіси й таблиці та допомагає тренерам виділитися серед конкурентів. Головна особливість — власний брендований застосунок тренера в App Store і Google Play з його логотипом, кольорами й персоналізованими функціями, який запускається менш ніж за 30 днів. Через застосунок клієнти записують харчування й тренування, проходять регулярні перевірки, переглядають прогрес, отримують доступ до преміум-контенту, надсилають голосові й текстові повідомлення. Серед нових функцій — накладання фото прогресу, яке чітко показує трансформацію клієнта. Функції створюються разом із тренерами. Є 14-денний безкоштовний період.', 'Kahunas is an all-in-one coaching platform that replaces clunky tools and spreadsheets and helps coaches stand out. Its key feature is the coach''s own branded app in the App Store and Google Play, with their logo, colors and personalized features, live in under 30 days. Through the app clients log nutrition and workouts, complete regular check-ins, view progress, access premium content and send voice notes and messages. New features include a progress photo overlay that clearly shows a client''s transformation. Features are built together with coaches. There is a 14-day free trial.', 'Брендований застосунок тренера в магазинах
Облік харчування й тренувань клієнтів
Регулярні перевірки клієнтів
Відстеження й накладання фото прогресу
Преміум-контент для клієнтів
Голосові й текстові повідомлення', 'Coach''s branded app in the stores
Client nutrition and workout logging
Regular client check-ins
Progress tracking and photo overlay
Premium content for clients
Voice notes and messaging', 'Онлайн-тренери й фітнес-коучі, які хочуть мати власний брендований застосунок.', 'Online trainers and fitness coaches who want their own branded app.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
