-- Pixellot — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pixellot.tv' OR LOWER(`name`) = LOWER('Pixellot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Pixellot', NULL, 'https://pixellot.tv', NULL, NULL, 'AI-камери для автоматичної зйомки, режисури й трансляції матчів без персоналу у 19 видах спорту, платформа для показу ігор уболівальникам та аналітика для тренерів, щоб покращувати тренування й ігрові плани.', 'AI cameras that automatically capture, produce and livestream games with no staff across 19 sports, a streaming platform for fans, and analytics that help coaches improve training and game plans.', 'Pixellot автоматично знімає, продюсує й транслює спортивні матчі за допомогою штучного інтелекту — без операторів і віддалено. Технологія працює для 19 видів спорту. Платформа для трансляцій з налаштовуваним інтерфейсом дозволяє показувати кожну гру на будь-якому екрані вболівальникам, родинам і тренерам. Для тренерів є інструменти аналізу, які відстежують різні аспекти гри, допомагають знаходити зони для покращення й точніше налаштовувати тренувальні та ігрові програми. Організації можуть заробляти на трансляціях, залучаючи вболівальників, рекрутерів і передплатників. Pixellot пропонує модель «камера як сервіс», у якій спортивні організації й медіакомпанії стають фінансовими партнерами. Рішення використовують від шкільного й студентського спорту в США до ліг у Європі, Африці та Азії.', 'Pixellot automatically captures, produces and streams sports games with AI, with no camera crew and remotely. The technology covers 19 sports. A streaming platform with a customizable interface lets you show every game on any screen to fans, families and coaches. Coaches get analysis tools that track every aspect of the game, help identify areas for improvement and fine-tune training and game programs. Organizations can earn revenue from streams by engaging fans, recruiters and subscribers. Pixellot offers a camera-as-a-service model in which sports organizations and media companies become financial partners. It is used from US high school and college sports to leagues in Europe, Africa and Asia.', 'Автоматична зйомка й режисура матчів
Підтримка 19 видів спорту
Платформа трансляцій для вболівальників
Аналітика гри для тренерів
Монетизація трансляцій
Модель «камера як сервіс»', 'Automatic game capture and production
Support for 19 sports
Streaming platform for fans
Game analytics for coaches
Stream monetization
Camera-as-a-service model', 'Спортивні організації, ліги, школи, університети й медіакомпанії.', 'Sports organizations, leagues, schools, colleges and media companies.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
