-- PlaySight — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'playsight.com' OR LOWER(`name`) = LOWER('PlaySight'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PlaySight', NULL, 'https://playsight.com', NULL, NULL, 'AI-камери для спортивних майданчиків: перетворюють корти, зали й ковзанки на «розумні» майданчики з багаторакурсною зйомкою, трансляціями, повторами, AI-хайлайтами й інструментами розвитку гравців. Є стаціонарна й портативна версії.', 'AI cameras for sports venues: they turn courts, gyms and rinks into smart venues with multi-angle recording, livestreams, replays, AI highlights and player development tools. Fixed and portable versions are available.', 'PlaySight — платформа розумних камер для спорту, яку використовують спортсмени, тренери, команди й ліги. Стаціонарне рішення SmartCourt перетворює корти, спортзали, ковзанки й інші майданчики на постійно підключений простір: камери знімають гру з потрібних ракурсів, а система забезпечує прямі трансляції, автоматичну режисуру, миттєві повтори й інструменти для розвитку гравців. Портативна версія дозволяє записувати й транслювати тренування, матчі й турніри без кабелів і мережевої інфраструктури. Інструменти монтажу зі штучним інтелектом за кілька кліків знаходять яскраві моменти й створюють хайлайти та тренерські кліпи для гравців. Технологія встановлена на тисячах кортів для паделу, пікболу й тенісу та використовується в професійному й студентському спорті. Для організацій доступна демонстрація.', 'PlaySight is a smart camera platform for sports used by athletes, coaches, teams and leagues. The fixed SmartCourt solution turns courts, gyms, rinks and other facilities into permanently connected venues: cameras capture play from sport-specific angles, while the system provides live streaming, automated production, instant replay and player development tools. The portable version records and streams practices, games and tournaments without cabling or network infrastructure. AI-powered editing tools find the best moments in a few clicks and create highlight videos and coaching clips for players. The technology is installed on thousands of padel, pickleball and tennis courts and is used in professional and collegiate sports. Organizations can schedule a demo.', 'Стаціонарні AI-камери SmartCourt для майданчиків
Портативна система без кабелів
Багаторакурсна зйомка й миттєві повтори
Прямі трансляції й автоматична режисура
AI-хайлайти й тренерські кліпи
Інструменти розвитку гравців', 'Fixed SmartCourt AI cameras for venues
Portable system with no cabling
Multi-angle recording and instant replay
Live streaming and automated production
AI highlights and coaching clips
Player development tools', 'Тренери, клуби, академії, ліги й власники спортивних майданчиків — теніс, падел, пікбол та командні види спорту.', 'Coaches, clubs, academies, leagues and venue owners in tennis, padel, pickleball and team sports.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
