INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PT Distinction', NULL, 'https://ptdistinction.com', NULL, NULL, 'Програма для персональних тренерів з усіма функціями в кожному тарифі: конструктор програм і AI-генератор програм за 20 секунд, AI-планувальник харчування, AI-помічник, оцінювання клієнтів, групові тренування, розсилки й автоматизація.', 'Personal trainer software with every feature in every plan: a program builder and an AI program generator in 20 seconds, an AI meal planner, an AI assistant, client assessments, group training, messaging and automation.', 'PT Distinction допомагає персональним тренерам вести більше клієнтів за менший час і з кращими результатами — усе необхідне зібрано в одному місці. Конструктор дозволяє створювати програми будь-якого типу, а AI-генератор складає індивідуальну програму приблизно за 20 секунд. Для харчування є інструменти коучингу й AI-планувальник раціону, який за секунди створює й редагує індивідуальні плани. AI-помічник за запитом пише статті для блогу, ідеї тренувань, рецепти тощо. Є вбудовані й власні оцінювання клієнтів, групові формати — челенджі, пробні програми, тренування в групах, повідомлення в застосунку, заплановані email і SMS, автоматизовані сценарії, звички, перевірка техніки, продаж пакетів і прийом оплат. На старшому тарифі — застосунки під власним брендом і інтеграція з сайтом. Перший місяць безкоштовний, без мінімального терміну.', 'PT Distinction helps personal trainers coach more clients in less time with better results, with everything in one place. The builder lets you create any type of program, and the AI generator produces a custom program in about 20 seconds. For nutrition there are coaching tools and an AI meal planner that creates and edits individual plans in seconds. The AI assistant writes blog posts, training ideas, recipes and more on request. There are built-in and custom client assessments, group formats such as challenges, trials and group training, in-app messaging, scheduled email and SMS, automated workflows, habits, exercise technique reviews, package sales and payments. The higher plan adds custom-branded apps and website integration. The first month is free, with no minimum term.', 'Конструктор і AI-генератор програм
AI-планувальник харчування
AI-помічник для контенту
Оцінювання клієнтів
Групові тренування й челенджі
Email, SMS і автоматизовані сценарії
Продаж пакетів і прийом оплат', 'Program builder and AI program generator
AI meal planner
AI assistant for content
Client assessments
Group training and challenges
Email, SMS and automated workflows
Package sales and payments', 'Персональні тренери й онлайн-коучі, які працюють з індивідуальними клієнтами та групами.', 'Personal trainers and online coaches working with individual clients and groups.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
