SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'spond.com' OR LOWER(`name`) = LOWER('Spond'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Spond', NULL, 'https://spond.com', NULL, NULL, 'Безкоштовний застосунок для організації команд, клубів і груп: планування подій і запрошення, збір оплат і внесків, фандрейзинг, керування учасниками й групами, реєстрація на курси — для тренерів, батьків і адміністраторів.', 'A free app for organizing teams, clubs and groups: event planning and invites, collecting payments, fundraising, member and group management and course registration, for coaches, parents and admins.', 'Spond — безкоштовний застосунок і рішення для керування клубом, яке спрощує організацію команд, клубів і груп у будь-якому виді спорту чи активності. Тренери й адміністратори груп швидко створюють групи, плануть події та розсилають запрошення, а учасники відповідають, чи прийдуть. Через застосунок можна збирати оплати й проводити фандрейзинг для групи. Для клубів є окремі функції: керування клубом, учасниками й групами, реєстрація на курси й клубний фандрейзинг. Застосунок зручний і для гравців, і для батьків та опікунів, які стежать за розкладом дітей, а також для організацій і шкіл. Spond користуються мільйони людей у тисячах клубів, а підтримка швидко відповідає на запитання.', 'Spond is a free app and club management solution that simplifies organizing teams, clubs and groups in any sport or activity. Coaches and group admins quickly set up groups, plan events and send invites, and participants reply whether they''re coming. The app lets you collect payments and run group fundraising. Clubs get dedicated features: club management, member and group management, course registration and club fundraising. The app works well for players, for parents and guardians following their children''s schedules, and for organizations and schools. Millions of people across thousands of clubs use Spond, and support answers questions quickly.', 'Планування подій і розсилка запрошень
Збір оплат і внесків
Фандрейзинг для груп і клубів
Керування учасниками й групами
Реєстрація на курси
Застосунок для гравців і батьків', 'Event planning and invites
Collecting payments and fees
Group and club fundraising
Member and group management
Course registration
App for players and parents', 'Тренери, адміністратори команд і клубів, гравці, батьки, школи й організації.', 'Coaches, team and club admins, players, parents, schools and organizations.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
