-- SportsEngine — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportsengine.com' OR LOWER(`name`) = LOWER('SportsEngine'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportsEngine', NULL, 'https://sportsengine.com', NULL, NULL, 'Набір програм для дитячого спорту: керування клубами, командами й лігами (розклади, реєстрація, оплати, застосунок команди), школами плавання й гімнастики, трансляції ігор з хайлайтами та організація турнірів.', 'A suite of software for youth sports: managing clubs, teams and leagues (schedules, registration, payments, team app), swim and gymnastics schools, game livestreams with highlights, and tournament organization.', 'SportsEngine, що тепер входить до PlayMetrics, — пов''язані технології для дитячого спорту. SportsEngine HQ допомагає клубам, командам і лігам: розклади, реєстрація й оплати, мобільний застосунок команди, фінанси й звіти — для бейсболу, американського футболу, хокею, лакросу та інших видів спорту. SportsEngine Motion (колишні GoMotion і TeamUnify) призначений для бізнесів із заняттями — плавання, черлідинг, гімнастика, танці, бойові мистецтва: розклад занять, онлайн-реєстрація й оплати, застосунок і бізнес-аналітика. SportsEngine Play дозволяє транслювати ігри на сайт, вирізати хайлайти, створювати добірки спортсменів, аналізувати гру після матчу й показувати рахунок поверх трансляції. SportsEngine Tourney автоматично будує турнірні сітки й розклади без конфліктів, а SportsEngine AES — платформа для волейбольних подій.', 'SportsEngine, now part of PlayMetrics, offers connected technology for youth sports. SportsEngine HQ serves clubs, teams and leagues with schedules, registration and payments, a team mobile app, and financials and reports for baseball, football, ice hockey, lacrosse and more. SportsEngine Motion (formerly GoMotion and TeamUnify) is for class-based businesses such as swimming, all-star cheer, gymnastics, dance and martial arts, with class schedules, online registration and payments, a mobile app and business analytics. SportsEngine Play lets you livestream games to your website, clip highlights, create athlete reels, analyze games afterward and overlay the score on streams. SportsEngine Tourney builds automated brackets and conflict-free schedules, and SportsEngine AES is a platform for volleyball events.', 'Розклади, реєстрація й оплати для клубів і ліг
Мобільний застосунок команди
Рішення для шкіл плавання, гімнастики й танців
Трансляції ігор і хайлайти спортсменів
Аналіз гри після матчу
Автоматичні турнірні сітки й розклади
Фінансові звіти', 'Schedules, registration and payments for clubs and leagues
Team mobile app
Solutions for swim, gymnastics and dance programs
Game livestreams and athlete highlights
Post-game analysis
Automated tournament brackets and schedules
Financial reports', 'Дитячі спортивні клуби, ліги, команди, школи плавання й гімнастики, організатори турнірів.', 'Youth sports clubs, leagues and teams, swim and gymnastics programs, tournament organizers.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
