-- Trace — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'traceup.com' OR LOWER(`name`) = LOWER('Trace'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Trace', NULL, 'https://traceup.com', NULL, NULL, 'Розумна камера для футболу: встановлюється за кілька хвилин, сама знімає все поле, а технологія PlayerFocus знаходить і веде кожного гравця, створює персональні хайлайти й аналітику для гравців, батьків, тренерів і скаутів.', 'A smart soccer camera: it sets up in minutes, records the whole pitch on its own, and PlayerFocus finds and follows every player, creating personal highlights and analytics for players, parents, coaches and recruiters.', 'Trace — смарт-камера для дитячого й аматорського футболу, яка знімає матч автоматично, тож батьки й тренери можуть просто бути на грі. Камера встановлюється за кілька хвилин і охоплює все поле. Штучний інтелект PlayerFocus знаходить і відстежує кожного гравця та дозволяє дивитися гру з фокусом на конкретній дитині: PlayerCam показує гравця крупним планом, ніби в нього власний оператор, а TraceCam дає тактичний вигляд усього епізоду. Можна додати смартфон для додаткових ракурсів. Автоматично створюються хайлайти гри, тактичні й персональні нарізки, а в розширеному плані — аналітика гравця й власний монтаж. Улюблені моменти зберігаються в публічному профілі, яким можна поділитися з рідними чи рекрутерами. Камера й штатив надаються в оренду в межах підписки.', 'Trace is a smart camera for youth and amateur soccer that records matches automatically, so parents and coaches can simply be present. It sets up in minutes and covers the entire pitch. PlayerFocus AI finds and tracks every player and lets you watch the game focused on one child: PlayerCam keeps your player front and center like a personal videographer, while TraceCam gives a tactical view of the whole play. You can add a smartphone for extra angles. Game, tactical and personal highlights are created automatically, and the higher plan adds player analytics and your own editing. Favorite moments are saved to a public profile you can share with family or recruiters. The camera and tripod are leased as part of the subscription.', 'Автоматична зйомка всього поля
Відстеження кожного гравця технологією PlayerFocus
Персональна камера на гравця PlayerCam
Тактичний вигляд TraceCam
Автоматичні хайлайти
Аналітика гравця
Публічний профіль для рекрутерів', 'Automatic full-pitch recording
PlayerFocus tracking of every player
PlayerCam personal camera on your player
TraceCam tactical view
Automatic highlights
Player analytics
Public profile for recruiters', 'Батьки юних футболістів, гравці, тренери й клуби дитячого та аматорського футболу.', 'Parents of young soccer players, players, coaches and clubs in youth and amateur soccer.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
