SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainingpeaks.com' OR LOWER(`name`) = LOWER('TrainingPeaks'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TrainingPeaks', NULL, 'https://trainingpeaks.com', NULL, NULL, 'Платформа для спортсменів на витривалість і їхніх тренерів: структуровані тренування й плани від досвідчених тренерів, синхронізація з пристроями, віртуальні заїзди, силова підготовка й пошук тренера в одному місці.', 'A platform for endurance athletes and their coaches: structured workouts and plans from experienced coaches, device sync, virtual rides, strength training and finding a coach, all in one place.', 'TrainingPeaks — повна тренувальна платформа для спортсменів і тренерів, яка поєднує планування, тренування й силову підготовку. Розділ планування дає змогу не гадати, а йти перевіреним шляхом: купувати плани від досвідчених тренерів, знаходити персонального тренера й виконувати структуровані тренування, щоб впевнено готуватися до стартів. Тренуватися можна в будь-якому виді спорту, з будь-яким пристроєм, удома й на вулиці. Структуровані тренування автоматично синхронізуються з сумісними пристроями й ведуть вас у реальному часі. TrainingPeaks Virtual пропонує динамічні віртуальні середовища з реалістичною фізикою для тренувань у приміщенні, де можна тренуватися з друзями. Модуль силової підготовки допомагає зміцнити тіло й захистити його від травм. Платформа особливо корисна з тренером, який веде спортсмена; реєстрація безкоштовна, є преміум-доступ.', 'TrainingPeaks is a complete training platform for athletes and coaches that combines planning, training and strength work. The planning side replaces guesswork with a proven path: buy plans from experienced coaches, find a personal coach and follow structured workouts to prepare for events with confidence. You can train for any sport, with any device, indoors and out. Structured workouts sync automatically with compatible devices and guide you in real time. TrainingPeaks Virtual offers high-energy immersive environments with real-world physics for indoor training with friends. The strength module helps you build strength and protect against injury. The platform is especially powerful with a coach guiding the athlete; sign-up is free and a premium tier is available.', 'Плани тренувань від досвідчених тренерів
Пошук персонального тренера
Структуровані тренування з синхронізацією на пристрої
Віртуальні тренування TrainingPeaks Virtual
Силова підготовка
Тренування в будь-якому виді спорту', 'Training plans from experienced coaches
Finding a personal coach
Structured workouts synced to devices
TrainingPeaks Virtual indoor training
Strength training
Training for any sport', 'Спортсмени на витривалість — бігуни, велосипедисти, тріатлоністи — і їхні тренери.', 'Endurance athletes, such as runners, cyclists and triathletes, and their coaches.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
