SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'truecoach.co' OR LOWER(`name`) = LOWER('TrueCoach'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TrueCoach', NULL, 'https://truecoach.co', NULL, NULL, 'Програма для персональних тренерів і власників залів для онлайн-тренувань клієнтів: конструктор програм, панель стану клієнтів, понад 3000 відео вправ, облік харчування й звичок, повідомлення, автоматичні оплати й публічний профіль тренера.', 'Software for personal trainers and gym owners to coach clients online: a program builder, client dashboard, 3,000+ exercise videos, nutrition and habit tracking, messaging, automated payments and a public coach profile.', 'TrueCoach допомагає персональним тренерам, коучам і власникам залів вести клієнтів онлайн і витрачати менше часу на адміністрування. Конструктор програм дозволяє один раз написати серію тренувань, а потім підлаштовувати її під кожного клієнта без повторного створення. Панель показує на одному екрані, що роблять клієнти й на якому етапі циклу вони перебувають. Усіх клієнтів і їхні тренування зручно вести в одному місці. Доступні бібліотека з понад 3000 відео вправ, облік харчування і звичок з інтеграцією MyFitnessPal, повідомлення в застосунку й безкоштовні автоматичні платежі. На старших тарифах з''являються публічний профіль тренера з заявками від клієнтів, дані з Apple, Garmin, WHOOP та інших носимих пристроїв, застосунок під власним брендом і автоматизації через Zapier. Є 14-денний безкоштовний період без картки.', 'TrueCoach helps personal trainers, coaches and gym owners train clients online and spend less time on admin. The program builder lets you write a series of workouts once and then customize it for each client without recreating it. The dashboard shows on one screen what clients are doing and where they are in their programming cycle. All clients and their workouts are managed in one place. You get a library of more than 3,000 exercise videos, nutrition and habit tracking with MyFitnessPal integration, in-app messaging and free automated payments. Higher plans add a public coach profile that lets clients apply to train with you, data from Apple, Garmin, WHOOP and other wearables, a custom-branded app and Zapier automations. There is a 14-day free trial with no credit card.', 'Конструктор програм тренувань
Панель стану всіх клієнтів
Понад 3000 відео вправ
Облік харчування й звичок, інтеграція MyFitnessPal
Повідомлення й автоматичні оплати
Дані з носимих пристроїв
Застосунок під власним брендом', 'Training program builder
Dashboard of all clients
3,000+ exercise videos
Nutrition and habit tracking with MyFitnessPal
Messaging and automated payments
Wearable data
Custom-branded app', 'Персональні тренери, онлайн-коучі й власники залів.', 'Personal trainers, online coaches and gym owners.', 'web,mobile,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
