SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'voltathletics.com' OR LOWER(`name`) = LOWER('Volt Athletics'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Volt Athletics', NULL, 'https://voltathletics.com', NULL, NULL, 'Науково обґрунтовані програми силової й фізичної підготовки, які штучний інтелект Cortex підлаштовує під ваші цілі, силу й обладнання. Програми для понад 40 видів спорту — для шкільних і університетських команд, тренерів і окремих спортсменів.', 'Science-based strength and conditioning programs that the Cortex AI adapts to your goals, strength and equipment. Programs for 40+ sports for high school and college teams, coaches and individual athletes.', 'Volt Athletics прибирає здогадки з тренувань команд і окремих спортсменів. Ви починаєте з програми, створеної сертифікованими тренерами з фізпідготовки під вимоги вашого виду спорту чи цілі, а запатентований штучний інтелект Cortex адаптує й розвиває тренування, щоб прогрес не зупинявся. Тренування підлаштовуються під вашу силу й доступне обладнання. Доступні програми для понад 40 видів спорту, активностей і цілей — від футболу до набору сили й маси. Volt використовують шкільні команди й уроки фізкультури, університетський спорт, тренерські бізнеси, армія й правоохоронні органи, великі організації, а окремі люди можуть безкоштовно спробувати застосунок Volt Training. Для команд доступна демонстрація, для всіх — безкоштовний пробний період.', 'Volt Athletics takes the guesswork out of training for teams and individuals. You start with a program designed by certified strength and conditioning coaches for the demands of your sport or goal, and the patented Cortex AI adapts and evolves your workouts so you never stop progressing. Workouts adjust to your strength and available equipment. Programs cover more than 40 sports, activities and goals, from soccer to strength and size. Volt is used by high school teams and P.E., college sports, training businesses, the military and law enforcement, and enterprises, and individuals can try the Volt Training app for free. Teams can request a demo, and everyone can start a free trial.', 'Програми від сертифікованих тренерів
Адаптація тренувань штучним інтелектом Cortex
Програми для понад 40 видів спорту
Урахування сили й обладнання
Рішення для шкіл, університетів і армії
Застосунок Volt Training для окремих спортсменів', 'Programs by certified coaches
Workouts adapted by the Cortex AI
Programs for 40+ sports
Adjusts to strength and equipment
Solutions for schools, colleges and the military
Volt Training app for individual athletes', 'Тренери шкільних і університетських команд, тренерські бізнеси, силові структури та окремі спортсмени.', 'High school and college team coaches, training businesses, tactical organizations and individual athletes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
