-- XPS Network — Для тренерів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sidelinesports.com' OR LOWER(`name`) = LOWER('XPS Network'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'XPS Network', NULL, 'https://sidelinesports.com', NULL, NULL, 'Програма для тренерів, клубів і федерацій від Sideline Sports: планування тренувань, спілкування з гравцями, моніторинг готовності й навантаження, тактичні схеми й анімації, відеоаналіз і облік травм у будь-якому виді спорту.', 'Software for coaches, clubs and associations from Sideline Sports: training planning, player communication, readiness and load monitoring, tactics diagrams and animations, video analysis and injury management in any sport.', 'XPS Network від Sideline Sports — платформа, яка допомагає тренерам будувати згуртовані команди й ухвалювати рішення на основі даних. Усе зберігається в одному місці: можна вибудувати навчальну програму згідно зі своєю тренерською філософією, планувати командні й індивідуальні тренування та бачити повну картину того, що відбувається в клубі. Тренер ділиться з гравцями підготовкою до матчів і тренувань та дає чіткі інструкції, а все спілкування ведеться в одному місці. Модуль моніторингу аналізує результати й тренувальні дані, стежить за готовністю, самопочуттям і навантаженням спортсменів. У розділі тактики можна малювати схеми й анімації, розбирати ігрові й тренувальні епізоди та одразу давати відгук гравцям. Є відеоаналіз, колекції вправ і облік травм. Платформа підтримує баскетбол, футбол, гандбол, хокей, теніс, волейбол та інші види спорту. Спробувати можна безкоштовно, без картки.', 'XPS Network by Sideline Sports is a platform that helps coaches build unified teams and make data-driven decisions. Everything is kept in one place: you can build a curriculum around your coaching philosophy, plan team and individual training and get a complete overview of what''s happening in the club. Coaches share match and training preparation with players and give clear instructions, with all communication in one place. The monitoring module analyzes performance and training data and tracks athlete readiness, wellness and training load. In the tactics section you create diagrams and animations, analyze game and training situations and give players instant feedback. There is also video analysis, collections and injury management. The platform supports basketball, football, handball, ice hockey, tennis, volleyball and other sports. You can try it free without a credit card.', 'Планування командних та індивідуальних тренувань
Спілкування з гравцями й підготовка до матчів
Моніторинг готовності, самопочуття й навантаження
Тактичні схеми й анімації
Відеоаналіз ігрових епізодів
Облік травм
Підтримка багатьох видів спорту', 'Team and individual training planning
Player communication and match prep
Readiness, wellness and load monitoring
Tactics diagrams and animations
Video analysis of game situations
Injury management
Support for many sports', 'Тренери, клуби й федерації в командних та індивідуальних видах спорту.', 'Coaches, clubs and associations in team and individual sports.', 'web,mobile,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
