INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'XPS Network by Sideline Sports is a platform that helps coaches build unified teams and make data-driven decisions. Everything is kept in one place: you can build a curriculum around your coaching philosophy, plan team and individual training and get a complete overview of what''s happening in the club. Coaches share match and training preparation with players and give clear instructions, with all communication in one place. The monitoring module analyzes performance and training data and tracks athlete readiness, wellness and training load. In the tactics section you create diagrams and animations, analyze game and training situations and give players instant feedback. There is also video analysis, collections and injury management. The platform supports basketball, football, handball, ice hockey, tennis, volleyball and other sports. You can try it free without a credit card.', 'manual' FROM DUAL WHERE @new = 1;
