-- Arccos — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'arccosgolf.com' OR LOWER(`name`) = LOWER('Arccos'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Arccos', NULL, 'https://arccosgolf.com', NULL, NULL, 'Розумні датчики для гольф-ключок і застосунок: автоматично записують кожен удар на полі, а штучний інтелект, навчений на понад мільярді ударів, показує, яку частину гри варто покращити, щоб знизити гандикап.', 'Smart sensors for golf clubs plus an app: they automatically record every shot on the course, and AI trained on over a billion shots shows which part of your game to work on to lower your handicap.', 'Arccos допомагає гольфістам зрозуміти, над чим насправді варто працювати. Більшість гравців витрачають час на тренування не того, що потрібно, а Arccos показує, що має значення. Розумні датчики кріпляться до ключок і автоматично відстежують кожен удар на полі, тож жоден раунд не залишиться незаписаним. Штучний інтелект, навчений на понад 1,5 мільярда ударів, аналізує всі аспекти вашої гри й дає персональні висновки, щоб ухвалювати кращі рішення на полі, швидше прогресувати й знижувати гандикап. Arccos — офіційний трекер гри PGA TOUR. В інтернет-магазині продаються датчики, аксесуари й одяг для гольфу.', 'Arccos helps golfers understand what they actually need to work on. Most golfers practice the wrong things, and Arccos shows what really matters. Smart sensors attach to your clubs and automatically track every shot on the course, so no round goes unrecorded. AI trained on more than 1.5 billion shots analyzes every aspect of your game and delivers personal insights so you make better decisions, improve faster and lower your handicap. Arccos is the official game tracker of the PGA TOUR. The online store sells sensors, accessories and apparel.', 'Розумні датчики для ключок
Автоматичний запис кожного удару
AI-аналіз гри
Персональні рекомендації, що покращити
Допомога в зниженні гандикапу
Аналітика всіх аспектів гри', 'Smart club sensors
Automatic recording of every shot
AI game analysis
Personal advice on what to improve
Help lowering your handicap
Analytics across every part of the game', 'Гольфісти-аматори й професіонали, які хочуть системно покращувати гру.', 'Amateur and pro golfers who want to improve their game systematically.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
