-- Diamond Kinetics — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'diamondkinetics.com' OR LOWER(`name`) = LOWER('Diamond Kinetics'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Diamond Kinetics', NULL, 'https://diamondkinetics.com', NULL, NULL, 'Датчик для бейсбольної чи софтбольної біти й застосунок: у реальному часі фіксує параметри замаху, відкриває уроки відбивання, ігри й челенджі з контентом MLB, а тренерам і скаутам дає орієнтири для оцінки гравців.', 'A sensor for baseball and softball bats plus an app: it captures swing metrics in real time, unlocks hitting lessons, games and challenges with MLB content, and gives coaches and scouts benchmarks for evaluating players.', 'Diamond Kinetics допомагає гравцям у бейсбол і софтбол прогресувати й отримувати більше задоволення від гри. Датчик DK кріпиться до будь-якої біти, у реальному часі фіксує дані замаху й одразу передає їх на iOS-пристрій. Ці дані запускають у застосунку уроки відбивання, ігри й челенджі; є ексклюзивний контент і активності від MLB, а преміум-підписка DK+ відкриває додаткові матеріали. Розумна біта Marucci має вбудований датчик у ручці, не потребує заряджання й допущена до використання в матчах. На основі мільйонів замахів щороку технологія надає гравцям, батькам, тренерам і скаутам орієнтири за всіма ключовими показниками для оцінки й розвитку гравців. Також можна транслювати матчі й ділитися хайлайтами з рідними. Технологію використовують MLB, USA Baseball, USA Softball та інші організації.', 'Diamond Kinetics helps baseball and softball players get better and have more fun doing it. The DK sensor attaches to any bat, captures swing data in real time and instantly sends it to an iOS device. The data drives in-app hitting lessons, games and challenges; there is exclusive MLB content and activities, and the DK+ subscription unlocks premium content. The Marucci smart bat has a sensor permanently fitted in the knob, needs no charging and is certified for in-game use. Based on millions of swings every year, the technology gives players, parents, coaches and scouts benchmarks across all key metrics for player evaluation and development. You can also livestream games and share highlights with family. It is used by MLB, USA Baseball, USA Softball and other organizations.', 'Датчик замаху для будь-якої біти
Дані замаху в реальному часі
Уроки відбивання, ігри й челенджі
Ексклюзивний контент MLB
Розумна біта Marucci з вбудованим датчиком
Орієнтири для оцінки гравців
Трансляції й хайлайти', 'Swing sensor for any bat
Real-time swing data
Hitting lessons, games and challenges
Exclusive MLB content
Marucci smart bat with built-in sensor
Benchmarks for player evaluation
Livestreams and highlights', 'Юні й дорослі бейсболісти та софтболісти, батьки, тренери й скаути.', 'Youth and adult baseball and softball players, parents, coaches and scouts.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
