-- HomeCourt — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'homecourt.ai' OR LOWER(`name`) = LOWER('HomeCourt'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HomeCourt', NULL, 'https://homecourt.ai', NULL, NULL, 'Баскетбольний застосунок із AI, який через камеру телефона записує кожен кидок, влучання, промахи й місце на майданчику, дає миттєвий відгук, пропонує інтерактивні вправи й віртуальні змагання з друзями та професіоналами.', 'An AI basketball app that uses your phone camera to record every shot, make, miss and court location, gives instant feedback, offers interactive drills and virtual competitions with friends and pros.', 'HomeCourt — інтерактивний баскетбольний застосунок, який працює як персональний тренер навичок, завжди під рукою. За допомогою штучного інтелекту він фіксує всі ваші кидки, рухи й статистику, тож знає ваш справжній рівень і в реальному часі показує, що вийшло й над чим працювати далі. Захопливі вправи й тренування більше нагадують відеогру, тому займатися цікаво й регулярно. Можна змагатися віртуально з друзями, родиною, партнерами по команді й гравцями з усього світу. Застосунок є офіційним партнером NBA і пропонує тренування й челенджі з відомими гравцями. Підписка HomeCourt+ відкриває повну історію тренувань, поглиблену аналітику й оцінки навичок, персональну програму щоденних тренувань і 5-денний онлайн-табір та дозволяє поділитися доступом із чотирма людьми. Для команд є групові плани з віддаленими тренуваннями, таблицями лідерів і переглядом відео кожного гравця.', 'HomeCourt is an interactive basketball app that works like a personal skills trainer you always have with you. Using AI, it captures all your shots, moves and stats, so it knows your true skill level and shows in real time what you did and what to work on next. Immersive drills and workouts feel more like a video game, so practice is fun and you stick with it. You can compete virtually with friends, family, teammates and players worldwide. The app is an official NBA partner and offers training and challenges featuring well-known players. The HomeCourt+ subscription unlocks full workout history, in-depth analytics and skill ratings, a personalized daily training program and a 5-day global camp, and can be shared with up to four people. Teams get group plans with remote practices, leaderboards and video review of each player.', 'Відстеження кидків, влучань і промахів через камеру
Миттєвий відгук і аналіз
Інтерактивні вправи у форматі гри
Віртуальні змагання з друзями
Персональна програма щоденних тренувань
Аналітика й оцінки навичок
Командні плани з таблицями лідерів і відеооглядом', 'Shot, make and miss tracking via the camera
Instant feedback and analysis
Game-like interactive drills
Virtual competitions with friends
Personalized daily training program
Analytics and skill ratings
Team plans with leaderboards and video review', 'Баскетболісти будь-якого рівня, юні гравці, тренери й команди.', 'Basketball players of every level, young players, coaches and teams.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
