INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'HomeCourt is an interactive basketball app that works like a personal skills trainer you always have with you. Using AI, it captures all your shots, moves and stats, so it knows your true skill level and shows in real time what you did and what to work on next. Immersive drills and workouts feel more like a video game, so practice is fun and you stick with it. You can compete virtually with friends, family, teammates and players worldwide. The app is an official NBA partner and offers training and challenges featuring well-known players. The HomeCourt+ subscription unlocks full workout history, in-depth analytics and skill ratings, a personalized daily training program and a 5-day global camp, and can be shared with up to four people. Teams get group plans with remote practices, leaderboards and video review of each player.', 'manual' FROM DUAL WHERE @new = 1;
