-- Ochy — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ochy.io' OR LOWER(`name`) = LOWER('Ochy'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ochy', NULL, 'https://ochy.io', NULL, NULL, 'AI-аналіз бігової техніки за відео з телефона: за 60 секунд без лабораторії й обладнання оцінює позу й рухи, знаходить причини можливих травм і дає рекомендації, як бігати ефективніше. Рішення є для бігунів, тренерів і фахівців.', 'AI running form analysis from phone video: in 60 seconds, with no lab or equipment, it assesses posture and movement, finds root causes of potential injuries and gives advice on running more efficiently. For runners, coaches and specialists.', 'Ochy робить біомеханічний аналіз лабораторної якості доступним кожному — без лабораторії, обладнання й датчиків. Ви вводите базові дані — зріст, вагу й темп, — знімаєте короткий біг збоку й ззаду на смартфон чи планшет, у приміщенні чи на вулиці, і за 60 секунд отримуєте персональний аналіз бігової техніки. Штучний інтелект допомагає знайти першопричину травм ще до того, як вони виникнуть, і дає практичні рекомендації, як рухатися краще, запобігати травмам і покращувати результати. Власний алгоритм розпізнавання пози, створений спеціально для бігу, відстежує положення суглобів. Методика спирається на понад 200 рецензованих досліджень, протестована на реальних бігунах і доопрацьована разом із провідними лабораторіями й академічними партнерами. Доступний застосунок і демонстрація для фахівців.', 'Ochy makes lab-quality biomechanics analysis accessible to everyone, with no lab, hardware or sensors. You enter basic details such as height, weight and pace, film a short run from the side and back on a smartphone or tablet, indoors or outdoors, and in 60 seconds get a personalized running gait analysis. The AI helps identify the root cause of injuries before they become problems and gives actionable recommendations to move better, prevent injury and boost performance. A proprietary pose estimation algorithm designed specifically for running tracks joint positions. The method is based on more than 200 peer-reviewed studies, tested with real runners and refined with leading labs and academic partners. An app and demos for professionals are available.', 'Аналіз бігової техніки за відео зі смартфона
Результат за 60 секунд
Без обладнання й датчиків
Пошук причин можливих травм
Персональні рекомендації щодо техніки
Методика на основі досліджень', 'Running form analysis from smartphone video
Results in 60 seconds
No equipment or sensors
Finding root causes of potential injuries
Personalized technique recommendations
Research-based method', 'Бігуни, бігові тренери, фізіотерапевти й магазини бігового спорядження.', 'Runners, running coaches, physiotherapists and running stores.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
