-- Onform — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'onform.com' OR LOWER(`name`) = LOWER('Onform'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Onform', NULL, 'https://onform.com', NULL, NULL, 'Застосунок для відеоаналізу в спорті: тренери знімають HD-відео в кількох режимах, розбирають техніку з малюванням, керуванням камерою й записом з кількох ракурсів, додають голосові коментарі й миттєво діляться відгуком зі спортсменами.', 'A sports video analysis app: coaches record HD video in several modes, break down technique with drawing tools, camera controls and multi-angle capture, add voice-overs and instantly share feedback with athletes.', 'Onform — платформа для відеокоучингу, яка допомагає тренерам підвищувати результати спортсменів через відеоаналіз. Принцип простий: записати, проаналізувати, поділитися. Відео у високій якості знімається в п''яти режимах, а потужні інструменти розбору допомагають детально проаналізувати техніку — є малювання поверх відео, розширені налаштування камери, зокрема витримки, порівняння з професійними еталонами. Тренер додає голосові коментарі й одразу ділиться відгуком через повідомлення в застосунку, а спортсмени, яких він веде, записують і надсилають відео безкоштовно. Старші плани дають необмежену кількість відео й коментарів, команд і спортсменів, запис із кількох ракурсів, сумісність із лаунч-моніторами та радарами швидкості, спільні колекції й інструменти для керування персоналом. Нове студійне рішення Multi-Cam MAX розширює багатокамерну зйомку. Застосунок використовують у гольфі, бейсболі, софтболі, легкій атлетиці, плаванні й інших видах спорту. Є 14-денний безкоштовний період без картки.', 'Onform is a video coaching platform that helps coaches improve athlete performance through video analysis. The principle is simple: record, analyze, share. HD video is captured in five recording modes, and powerful tools help break down technique in detail, with drawing over video, advanced camera controls such as shutter speed, and professional reference content for comparison. Coaches add voice-overs and share feedback instantly through in-app messaging, and coached athletes always record and share for free. Higher plans offer unlimited videos and voice-overs, teams and athletes, multi-angle capture, launch monitor and speed radar compatibility, shared collections and staff management tools. The new Multi-Cam MAX studio solution extends multi-camera capture. The app is used in golf, baseball, softball, track and field, swimming and other sports. There is a 14-day free trial with no credit card.', 'HD-зйомка в п''яти режимах
Малювання й аналіз техніки на відео
Голосові коментарі до відео
Запис із кількох ракурсів
Інтеграція з лаунч-моніторами й радарами
Миттєвий обмін відгуком зі спортсменами
Професійні еталонні відео', 'HD recording in five modes
Drawing and technique analysis on video
Voice-overs on videos
Multi-angle capture
Launch monitor and radar integration
Instant feedback sharing with athletes
Professional reference videos', 'Тренери й спортсмени в гольфі, бейсболі, софтболі, легкій атлетиці, плаванні та інших видах спорту.', 'Coaches and athletes in golf, baseball, softball, track and field, swimming and other sports.', 'mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
