-- Output Sports — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'outputsports.com' OR LOWER(`name`) = LOWER('Output Sports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Output Sports', NULL, 'https://outputsports.com', NULL, NULL, 'Один портативний датчик і застосунок для тренерів із фізпідготовки, тренерів і фізіотерапевтів: тренування зі швидкістю руху, тести стрибків і реактивної сили, рухливості, балансу та сили, а також програмування тренувань.', 'One portable sensor and app for strength coaches, trainers and physios: velocity-based training, jump and reactive strength tests, mobility, balance and strength testing, plus training programming.', 'Output Sports об''єднує в одній системі тренування з контролем швидкості руху, тестування спортсменів і програмування тренувань. Один портативний датчик і застосунок створені для тренерів із фізпідготовки, тренерів і фізіотерапевтів, які цінують ефективний коучинг на основі даних і хочуть ухвалювати рішення, а не тонути в цифрах. Система вимірює швидкість, силу, потужність і роботу у вправах зі штангою, трап-грифом і гантелями, оцінює стрибки й індекс реактивної сили, діапазон рухів суглобів від щиколотки до шиї, кидки й махи з медболами та гирями, а також баланс, стабільність, силу, витривалість і самопочуття. Нова платформа Output Program допомагає складати й вести тренувальні програми. Ціни надаються під час демонстрації; діє 30-денна гарантія повернення коштів.', 'Output Sports combines velocity-based training, athlete testing and programming in one system. A single portable sensor and app are built for strength coaches, trainers and physios who value efficient, data-driven coaching and want to make decisions rather than drown in data. The system measures velocity, force, power and work in barbell, trap-bar and dumbbell lifts, assesses jumps and reactive strength index, range of motion across joints from ankle to neck, slams, swings and throws with medicine balls and kettlebells, as well as balance, stability, strength, endurance and wellness. The new Output Program platform helps build and run training programs. Pricing is shared during a demo, and there is a 30-day money-back guarantee.', 'Тренування зі швидкістю руху штанги
Тести стрибків і реактивної сили
Оцінка рухливості суглобів
Баланс, стабільність і сила
Вимірювання кидків і махів
Програмування тренувань Output Program
Один портативний датчик', 'Velocity-based barbell training
Jump and reactive strength tests
Joint mobility assessment
Balance, stability and strength
Measuring throws and swings
Output Program training programming
One portable sensor', 'Тренери з фізпідготовки, персональні тренери й фізіотерапевти.', 'Strength and conditioning coaches, personal trainers and physiotherapists.', 'mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
