INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Output Sports combines velocity-based training, athlete testing and programming in one system. A single portable sensor and app are built for strength coaches, trainers and physios who value efficient, data-driven coaching and want to make decisions rather than drown in data. The system measures velocity, force, power and work in barbell, trap-bar and dumbbell lifts, assesses jumps and reactive strength index, range of motion across joints from ankle to neck, slams, swings and throws with medicine balls and kettlebells, as well as balance, stability, strength, endurance and wellness. The new Output Program platform helps build and run training programs. Pricing is shared during a demo, and there is a 30-day money-back guarantee.', 'manual' FROM DUAL WHERE @new = 1;
