INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Runeasi is a platform that gives physios and coaches objective data to guide rehab, injury prevention and performance for runners. Visual assessment doesn''t show how clients respond to load, manual reporting takes time, and clients lose motivation when they can''t see improvement. Runeasi addresses this with one tool for running and jumping that measures load, stability, power, reactivity and symmetry. The metrics are validated against force plates and 3D motion capture. Setup takes under 60 seconds, and you can test anywhere: treadmill, court, track or trail. Instant reports boost client motivation and adherence, the system suggests data-driven exercises and provides real-time data for gait retraining. Reports also work as marketing content for social media. Demos are available.', 'manual' FROM DUAL WHERE @new = 1;
