-- Sency — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sency.ai' OR LOWER(`name`) = LOWER('Sency'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sency', NULL, 'https://sency.ai', NULL, NULL, 'Технологія відстеження рухів за допомогою камери телефона для фітнес- і медичних платформ: SDK, який за день вбудовується в застосунок і в реальному часі аналізує рухи людини, допомагаючи бізнесу утримувати й залучати користувачів.', 'Movement tracking with a phone camera for fitness and health platforms: an SDK that integrates into an app in about a day and analyzes human movement in real time, helping businesses engage and retain users.', 'Sency — технологія комп''ютерного зору, яка розпізнає будь-які рухи людини й у реальному часі дає зрозумілі висновки. Вона призначена для компаній, що створюють фітнес- і медичні платформи: достатньо камери мобільного пристрою й набору розробника Sency Motion SDK, щоб одразу почати відстежувати рухи користувачів. Технологія допомагає підвищити задоволеність, залученість і утримання користувачів, а отже, й дохід бізнесу; рішення підлаштовують під конкретні цілі компанії. Інтеграція займає близько дня й безкоштовна, інтерфейс можна оформити у власному стилі, а кількість активностей на користувача не обмежена. Є безкоштовний пробний період, далі — оплата залежно від кількості активних користувачів. Партнери використовують Sency, зокрема, для фітнес-оцінювання у своїх застосунках.', 'Sency is a computer vision technology that captures any human movement and delivers actionable insights in real time. It is built for companies creating fitness and health platforms: a mobile camera and the Sency Motion SDK are all you need to start tracking user movements right away. The technology helps raise user satisfaction, engagement and retention, and with them revenue; the solution is tailored to each company''s goals. Integration takes about a day and is free, the UI can be branded, and activities per user are unlimited. There is a free trial, then pricing is based on monthly active users. Partners use Sency, for example, for fitness assessments in their apps.', 'Відстеження рухів через камеру телефона
Аналіз рухів у реальному часі
SDK для вбудовування в застосунки
Інтеграція приблизно за день
Інтерфейс у стилі вашого бренду
Безлімітні активності на користувача', 'Movement tracking via phone camera
Real-time movement analysis
SDK for embedding in apps
Integration in about a day
Branded UI
Unlimited activities per user', 'Компанії, які розробляють фітнес-, реабілітаційні й медичні застосунки.', 'Companies building fitness, rehabilitation and health apps.', 'mobile', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
