-- Sportsbox AI — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportsbox.ai' OR LOWER(`name`) = LOWER('Sportsbox AI'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportsbox AI', NULL, 'https://sportsbox.ai', NULL, NULL, '3D-аналіз гольф-свінгу зі смартфона: перетворює складні дані про рух на прості поради, порівнює ваші свінги, автоматизує тренування, а AI-експерт SAMI відповідає на запитання й підказує, що покращити саме у вашому свінгу.', '3D golf swing analysis from a smartphone: it turns complex motion data into simple advice, compares your swings, automates practice, and the SAMI AI expert answers questions and suggests what to improve in your own swing.', 'Sportsbox AI розробляє застосунки «AI-тренер» для спорту й фітнесу на основі технології 3D-аналізу руху. Флагманський продукт — аналіз гольф-свінгу, який перетворює складні дані про рух на прості й практичні поради. Замість загальних рекомендацій ви отримуєте відгук, заснований на спортивній науці, мільйонах проаналізованих свінгів і вашому власному русі. Застосунок показує детальні 3D-дані, дозволяє порівнювати свінги між собою та автоматизує тренування, тож кожна сесія має мету, а ви бачите, коли справді покращуєтеся. AI-експерт SAMI використовує ваші 3D-дані, щоб відповідати на запитання, знаходити закономірності й підказувати наступні кроки. Технологією користуються професійні гравці турів і тренери з гольфу.', 'Sportsbox AI develops AI coach apps for sports and fitness based on 3D motion analysis technology. Its flagship product is golf swing analysis that turns complex motion data into simple, actionable feedback. Instead of generic advice, you get feedback grounded in sports science, informed by millions of swings and shaped by your own movement. The app shows in-depth 3D data, lets you compare swings and automates practice, so every session has a purpose and you know when you are actually improving. The SAMI AI expert uses your 3D data to answer questions, uncover insights and guide your next steps. Tour professionals and golf coaches use the technology.', '3D-аналіз гольф-свінгу зі смартфона
Прості практичні поради замість сирих даних
Порівняння свінгів
Автоматизовані тренування
AI-експерт SAMI
Відстеження покращень', '3D golf swing analysis from a smartphone
Simple actionable feedback instead of raw data
