-- Swing Catalyst — Аналіз техніки та біомеханіка
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'swingcatalyst.com' OR LOWER(`name`) = LOWER('Swing Catalyst'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Swing Catalyst', NULL, 'https://swingcatalyst.com', NULL, NULL, 'Програма для аналізу замаху в гольфі й бейсболі: до чотирьох синхронних високошвидкісних відео, дані з силових і тискових платформ та лаунч-моніторів, безмаркерне захоплення руху, інструменти малювання й відеоуроки для учнів.', 'Swing analysis software for golf and baseball: up to four synchronized high-speed videos, force and pressure plate and launch monitor data, markerless motion capture, drawing tools and video lessons for students.', 'Swing Catalyst робить детальний аналіз замаху простим і допомагає тренерам прибрати здогадки з навчання. Програма записує до чотирьох повністю синхронізованих високошвидкісних відеопотоків і об''єднує їх із даними силових і тискових платформ та лаунч-моніторів. Інструменти малювання, накладання відео й порівняння пліч-о-пліч допомагають швидко оцінювати замахи й вимірювати прогрес. Вбудована функція відеоуроків дозволяє записувати й надсилати учням короткі підсумки заняття, щоб відстежувати прогрес і тримати клієнтів залученими. У тарифах Pro і Pro+ є безмаркерне захоплення руху без датчиків, проводів і калібрування: у реальному часі видно кути суглобів, центр мас і силові дані в одному синхронному вигляді. Власні сенсорні платформи Swing Catalyst дають точні дані в реальному часі. Програма працює на Windows 11; є безкоштовна спроба.', 'Swing Catalyst makes advanced swing analysis easy and takes the guesswork out of coaching. The software captures up to four fully synchronized high-speed video streams and integrates data from force and pressure plates and launch monitors. Drawing tools, video overlays and side-by-side comparisons help you assess swings quickly and measure improvement. The built-in video lesson feature lets you record and share lesson summaries with students to track progress and keep clients engaged. Pro and Pro+ subscriptions include markerless motion capture with no markers, wires or calibration, showing joint angles, center of mass and force data in one synchronized real-time view. Swing Catalyst''s own sensor plates deliver precise real-time data. The software runs on Windows 11, and a free trial is available.', 'До 4 синхронних високошвидкісних відео
Дані силових і тискових платформ
Інтеграція з лаунч-моніторами
Безмаркерне захоплення руху
Малювання й порівняння замахів
Відеоуроки для учнів', 'Up to 4 synchronized high-speed videos
Force and pressure plate data
Launch monitor integration
Markerless motion capture
