INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Trackman', NULL, 'https://trackman.com', NULL, NULL, 'Лаунч-монітори й гольф-симулятори, перевірені на професійних турнірах, для дому й клубів, а також системи відстеження для бейсболу та футболу: точні дані про удар, реалістична графіка й інструменти для тренерів і гольф-клубів.', 'Tour-proven launch monitors and golf simulators for home and clubs, plus tracking systems for baseball and football: accurate shot data, realistic graphics and tools for coaches and golf facilities.', 'Trackman створює лаунч-монітори й симуляторні технології, якими користуються професіонали, тренери й любителі. Системи вимірюють параметри удару й польоту м''яча та поєднуються з реалістичною графікою для гри в приміщенні; є рішення для дому й для комерційного використання. Домашній гольф-симулятор дозволяє тренуватися, грати й покращувати гру з високою точністю. Для гольф-клубів платформа Trackman 360 об''єднує тренування, тренувальні поля, симулятори, застосунок і бізнес-інструменти, щоб клуби працювали ефективніше, а члени залишалися залученими цілий рік. Графічний рушій Virtual Golf 3 робить гру в симуляторі ще реалістичнішою. Окрім гольфу, Trackman пропонує портативні системи й відстеження ігор для бейсболу, а також рішення для футболу та американського футболу. Симулятори коштують від 13 995 USD.', 'Trackman builds launch monitors and simulator technology used by professionals, coaches and enthusiasts. The systems measure shot and ball flight data and pair it with realistic graphics for indoor play, with solutions for home and commercial use. The home golf simulator lets you practice, play and improve with high accuracy. For golf facilities, the Trackman 360 platform brings together coaching, range, simulators, the app and business tools so clubs run more efficiently and members stay engaged year-round. The Virtual Golf 3 graphics engine makes simulator play even more realistic. Beyond golf, Trackman offers portable systems and game tracking for baseball, as well as solutions for football and American football. Simulators start at USD 13,995.', 'Лаунч-монітори для гольфу
Гольф-симулятори для дому й клубів
Реалістична графіка Virtual Golf 3
Платформа Trackman 360 для гольф-клубів
Системи для бейсболу з відстеженням ігор
Рішення для футболу', 'Golf launch monitors
Golf simulators for home and clubs
Realistic Virtual Golf 3 graphics
Trackman 360 platform for golf facilities
Baseball systems with game tracking
Football solutions', 'Гольфісти, тренери з гольфу, гольф-клуби, а також бейсбольні й футбольні команди.', 'Golfers, golf coaches, golf facilities, and baseball and football teams.', 'mobile,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
