SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'valdperformance.com' OR LOWER(`name`) = LOWER('VALD'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VALD', NULL, 'https://valdperformance.com', NULL, NULL, 'Технології для вимірювання фізичних можливостей: системи VALD допомагають командам, залам, університетам і силовим структурам вимірювати силу, потужність, рух, баланс і асиметрію спортсменів та керувати їхньою підготовкою.', 'Technology for measuring physical performance: VALD systems help teams, gyms, universities and tactical organizations measure athletes'' strength, power, movement, balance and asymmetry and manage their training.', 'VALD робить передові технології спортивної науки доступними для будь-якої команди. Обладнання й програми VALD допомагають вимірювати, контролювати й покращувати силу, потужність, рухливість, баланс, асиметрію та інші фізичні показники команд і спортсменів. Їх використовують у десятках видів спорту — на кортах, полях, доріжках, в індивідуальних і командних дисциплінах, — а також в елітних клубах, приватних залах, університетах, школах, рятувальних службах, оборонних відомствах і навіть у виконавських мистецтвах. Системи застосовують для фізичного профілювання, моніторингу, рішень про повернення до гри після травм, пошуку талантів та інших задач. Технологіям довіряють професійні ліги, провідні університетські програми, клуби англійської Прем''єр-ліги й національні спортивні організації.', 'VALD makes cutting-edge sports science technology accessible to every team. VALD hardware and software help measure, manage and improve the strength, power, movement, balance, asymmetry and other physical qualities of teams and athletes. They are used in dozens of sports, on courts, fields and tracks, in individual and team disciplines, as well as by elite clubs, private gyms, universities, schools, emergency services, defense departments and even the performing arts. The systems support profiling, monitoring, return-to-play decisions, talent identification and more. VALD is trusted by major league franchises, leading college programs, Premier League clubs and national sporting organizations.', 'Вимірювання сили й потужності
Оцінка рухливості, балансу й асиметрії
Фізичне профілювання спортсменів
Моніторинг стану й підготовки
Рішення про повернення до гри
Пошук талантів', 'Strength and power measurement
Movement, balance and asymmetry assessment
Athlete physical profiling
Readiness and training monitoring
Return-to-play decisions
Talent identification', 'Професійні й університетські команди, зали, школи, національні спортивні організації, оборонні й рятувальні служби.', 'Pro and college teams, gyms, schools, national sporting organizations, defense and emergency services.', 'web,mobile', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
