-- Athletica — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'athletica.ai' OR LOWER(`name`) = LOWER('Athletica'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Athletica', NULL, 'https://athletica.ai', NULL, NULL, 'Адаптивні плани тренувань на витривалість на основі спортивної науки для бігунів, велосипедистів, тріатлоністів і веслярів: план підлаштовується під форму, втому й графік, а розмовний AI-тренер пояснює ваші дані.', 'Science-based adaptive endurance training plans for runners, cyclists, triathletes and rowers: the plan adjusts to your fitness, fatigue and schedule, and a conversational AI coach explains your data.', 'Athletica — адаптивна система тренувань на витривалість для бігунів, велосипедистів, тріатлоністів, дуатлоністів, веслярів і гібридних спортсменів, а також їхніх тренерів, які цінують довгостроковий прогрес. Плани автоматично підлаштовуються під вашу форму, втому й розклад, щоб ви прогресували впевнено. Пропущене тренування, переліт чи поганий сон не руйнують план — система його адаптує, допомагаючи зберігати регулярність, уникати перевтоми й підійти до старту підготовленим. Розмовний AI-тренер враховує історію тренувань, форму й втому: можна поставити запитання й отримати конкретну відповідь на основі ваших даних, а не просто набір цифр. Усі плани дають повний доступ до платформи без поділу на рівні. Є двотижневий безкоштовний період без картки.', 'Athletica is an adaptive endurance training system for runners, cyclists, triathletes, duathletes, rowers and hybrid athletes, as well as coaches who value long-term progress. Plans automatically adjust to your fitness, fatigue and schedule so you improve with confidence. A missed workout, a travel day or bad sleep doesn''t blow up the plan; the system adapts it, helping you stay consistent, avoid burnout and arrive at race day prepared. A conversational AI coach understands your training history, fitness and fatigue: you can ask a question and get a real answer based on your data instead of just a set of numbers. Every plan includes full platform access with no tiers. There is a two-week free trial with no credit card.', 'Адаптивні плани тренувань на витривалість
Урахування форми, втоми й графіка
Розмовний AI-тренер
