INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Athlytic helps you know when to push, when to back off and how hard to go today. The app uses your Apple Health data and each morning shows one clear recovery score from 0 to 100%, based on heart rate variability and resting heart rate during sleep. Recovery becomes a personalized Target Exertion Zone for the day, and during workouts exertion builds in real time on your watch so you can see when you hit the zone. The daily dashboard shows four key numbers: recovery, cardiovascular exertion on a 0–10 scale, the target zone and sleep quality including sleep debt and consistency. There is also a journal with impact analysis, 24/7 health monitoring, workout tracking, an Athlytic Age and cycle-aware training. Apple Watch widgets are available.', 'manual' FROM DUAL WHERE @new = 1;
