INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Catapult is a global sports technology company that helps leagues, teams and organizations unlock athlete potential with data and analytics. Its core is athlete monitoring: the flagship Vector Pro tracks athletes outdoors and indoors using GPS and a local positioning system, measures heart rate, inertial data and more than 15 live metrics, and integrates with video analysis to put athlete data in context. Vector Core offers many of the same features in a more compact package. Beyond monitoring there is a video analysis platform, scouting and recruitment solutions and motorsport solutions. Catapult serves football, American football, rugby, ice hockey, cricket, baseball and basketball and works with thousands of elite teams in more than a hundred countries. Pricing is tailored to each team.', 'manual' FROM DUAL WHERE @new = 1;
