SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'enduco.app' OR LOWER(`name`) = LOWER('enduco'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'enduco', NULL, 'https://enduco.app', NULL, NULL, 'Персональні плани тренувань для бігу, велоспорту й тріатлону на основі даних: постійно підлаштовуються під ваші цілі, поточну форму й повсякденне життя, щодня оцінюють ваш стан і дають корисні поради.', 'Data-driven personal training plans for running, cycling and triathlon: they continuously adapt to your goals, current fitness and daily life, assess your condition every day and give helpful tips.', 'enduco допомагає спортсменам розкрити свій потенціал завдяки науково обґрунтованим тренуванням з бігу, велоспорту, плавання й тріатлону. Плани підлаштовуються під вас, а не навпаки: вони постійно враховують ваші цілі, поточний рівень підготовки й повсякденне життя. Ви визначаєте особисту ціль — почати тренуватися, підкорити 5 км чи пробігти марафон, — і enduco складає точний план саме для вас. Протягом підготовки застосунок супроводжує вас, щодня оцінює ваш стан і дає корисні поради. У календарі кожне тренування підібране під ваші цілі, а плани доповнені порадами спортсменів світового рівня й людей, які надихають. Підходить і для першого старту, і для найбільшого виклику.', 'enduco helps athletes reach their full potential with science-backed training for running, cycling, swimming and triathlon. Plans adapt to you, not the other way around: they continuously take into account your goals, current fitness and everyday life. You define a personal goal, such as getting started, conquering a 5K or running a marathon, and enduco crafts a precise plan for you. Throughout your preparation the app guides you, assesses your daily situation and gives helpful tips. In the calendar every workout is matched to your goals, and plans are enhanced with tips from world-class athletes and inspiring personalities. It suits both a first race and your biggest challenge yet.', 'Персональні плани для бігу, велоспорту й тріатлону
Адаптація під цілі, форму й повсякденне життя
Щоденна оцінка стану
Персональні поради
Календар тренувань
Поради від спортсменів світового рівня', 'Personal plans for running, cycling and triathlon
Adapts to goals, fitness and daily life
Daily condition assessment
Personal tips
Training calendar
Tips from world-class athletes', 'Бігуни, велосипедисти й тріатлоністи — від новачків до досвідчених спортсменів.', 'Runners, cyclists and triathletes, from beginners to experienced athletes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
