-- Garmin Connect — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'connect.garmin.com' OR LOWER(`name`) = LOWER('Garmin Connect'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Garmin Connect', NULL, 'https://connect.garmin.com', NULL, NULL, 'Застосунок і веб-сервіс для власників пристроїв Garmin: відстежує й аналізує тренування та показники здоров''я, показує тижневі, місячні й річні тренди, дає адаптивні тренування від Garmin Coach і змагання з друзями.', 'An app and web service for Garmin device owners: it tracks and analyzes workouts and health stats, shows weekly, monthly and yearly trends, and offers adaptive Garmin Coach workouts and challenges with friends.', 'Garmin Connect — інструмент для відстеження, аналізу й поширення даних про здоров''я та фізичну активність із пристроїв Garmin на телефоні й у веб-версії. Ви встановлюєте застосунок, тренуєтеся з пристроєм Garmin і бачите свій прогрес. Головний екран показує ключові дані здоров''я в тому порядку, який вам зручний, а детальний аналіз включає тижневі, місячні й річні середні значення та історію улюблених активностей. Сервіс відстежує біг, плавання, каякінг, силові й багато інших видів активності, а записана статистика допомагає аналізувати результати й покращувати їх наступного разу. Garmin Coach пропонує тренування, що підлаштовуються під ваш рівень, персональні поради, статті й відео. З друзями можна змагатися в челенджах за кроками й дистанцією, створювати групи, підтримувати одне одного й отримувати бейджі.', 'Garmin Connect is the tool for tracking, analyzing and sharing health and fitness activities from your Garmin device, on mobile or the web. You install the app, get active with your Garmin device and view your progress. The home screen shows your key health data in the order you choose, and detailed analysis includes weekly, monthly and yearly averages and history of your favorite activities. It tracks running, swimming, kayaking, weightlifting and many other activities, and the recorded stats help you analyze your performance and improve next time. Garmin Coach offers workouts that adapt to your ability, personalized coaching advice, articles and videos. With friends you can compete in step and distance challenges, create groups, cheer each other on and earn badges.', 'Відстеження тренувань і показників здоров''я
Тижневі, місячні й річні тренди
Адаптивні тренування Garmin Coach
Підтримка багатьох видів спорту
Челенджі й групи з друзями
Мобільна й веб-версія', 'Workout and health tracking
Weekly, monthly and yearly trends
Adaptive Garmin Coach workouts
Support for many sports
Challenges and groups with friends
Mobile and web versions', 'Власники годинників і пристроїв Garmin, які займаються бігом, плаванням, велоспортом та іншими видами спорту.', 'Owners of Garmin watches and devices who run, swim, cycle or do other sports.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
