-- Hexis — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hexis.live' OR LOWER(`name`) = LOWER('Hexis'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hexis', NULL, 'https://hexis.live', NULL, NULL, 'Технологія спортивного харчування: на основі ваших тренувальних даних складає персональний план харчування під кожне заняття, позначаючи прийоми їжі кольорами за кількістю вуглеводів. Працює з Garmin, TrainingPeaks, Intervals.icu, WHOOP і Apple Health.', 'Sports nutrition technology: from your training data it builds a personal fueling plan for every session, color-coding meals by carbohydrate needs. Works with Garmin, TrainingPeaks, Intervals.icu, WHOOP and Apple Health.', 'Hexis допомагає спортсменам і командам персоналізувати й періодизувати харчування та стратегії відновлення. Майже кожен спортсмен на витривалість має план тренувань, але рідко — план харчування, і Hexis заповнює цю прогалину. Сервіс будує персональні плани на основі ваших тренувальних даних і наукових підходів елітного спорту. Головна ідея — «кодування вуглеводів»: важкі дні й дні відпочинку не можна забезпечувати енергією однаково, тож кожен прийом їжі отримує колір залежно від того, яку роботу ви щойно виконали й що чекає попереду. Зелений означає багато вуглеводів перед важким чи довгим заняттям, жовтий — помірну кількість для рівного тренування, червоний — мало вуглеводів у легкий день чи день відпочинку. Підтримуються біг, плавання, силові, велоспорт і ще понад 80 видів активності. Hexis інтегрується з Garmin, TrainingPeaks, Intervals.icu, WHOOP і Apple Health. Є безкоштовний калькулятор плану харчування.', 'Hexis helps athletes and teams personalize and periodize their fueling and recovery strategies. Almost every endurance athlete has a training plan, but very few have a fueling plan, and Hexis fills that gap. It builds personal plans from your training data and the science behind elite sport. The core idea is Carb Coding: hard days and rest days shouldn''t be fueled the same, so each meal gets a color based on the work you''ve just done and the work ahead. Green means high carb before a hard or long session, amber means moderate carb for steady training, and red means low carb on an easy or rest day. Running, swimming, strength, cycling and more than 80 other activities are supported. Hexis integrates with Garmin, TrainingPeaks, Intervals.icu, WHOOP and Apple Health. A free fuel plan calculator is available.', 'Персональний план харчування під кожне тренування
Кольорове кодування вуглеводів у прийомах їжі
Стратегії відновлення
Понад 80 видів активності
Інтеграція з Garmin, TrainingPeaks, WHOOP, Apple Health
Безкоштовний калькулятор плану харчування', 'Personal fueling plan for every session
Color-coded carbohydrates per meal
Recovery strategies
80+ activities
Integration with Garmin, TrainingPeaks, WHOOP, Apple Health
Free fuel plan calculator', 'Спортсмени на витривалість, команди й організації високих досягнень.', 'Endurance athletes, teams and high-performance organizations.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
