-- Plantiga — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'plantiga.com' OR LOWER(`name`) = LOWER('Plantiga'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Plantiga', NULL, 'https://plantiga.com', NULL, NULL, 'Устілки-датчики з AI для спортсменів: вимірюють асиметрію й навантаження разом прямо на полі, майданчику чи льоду, допомагають ухвалювати рішення про повернення після травми, рано помічати ризики й зберігати форму протягом сезону.', 'AI-powered in-shoe sensors for athletes: they measure asymmetry and load together right on the court, field or ice, support return-to-play decisions, flag injury risk early and help maintain performance across the season.', 'Plantiga — платформа з датчиками у взутті й штучним інтелектом для оцінки реабілітації, виявлення ризику травм і контролю повернення до спорту. Силові платформи вимірюють якість руху в лабораторії, GPS — обсяг роботи на полі, але жоден із цих інструментів не показує обидва аспекти там, де спортсмени змагаються. Датчики Plantiga вимірюють асиметрію й навантаження разом на кожному тренуванні — на майданчику, полі, льоду чи доріжці. Система допомагає ухвалювати впевнені рішення про повернення до гри на основі об''єктивних даних, перевіряючи функціональну готовність і переносимість навантаження. Модуль Norman.ai постійно стежить за біомеханікою й позначає дрібні зміни та асиметрії, перш ніж вони переростуть у проблему. Також платформа допомагає оптимізувати щоденне механічне навантаження й зберегти ефективні рухові патерни протягом виснажливого сезону. Почати можна з одного спортсмена.', 'Plantiga is an AI and in-shoe sensor platform for quantifying rehab, highlighting injury risk and monitoring return to sport. Force plates measure movement quality in the lab and GPS counts volume on the field, but neither shows both where athletes actually compete. Plantiga''s in-shoe sensors measure asymmetry and load together, every session, on the court, field, ice or track. The system supports confident return-to-play decisions with objective data by validating functional readiness and load tolerance. Norman.ai provides continuous biomechanical surveillance, flagging subtle micro-changes and asymmetries before they escalate. The platform also helps optimize daily mechanical load and preserve efficient movement patterns through demanding seasons. You can start with a single athlete.', 'Датчики-устілки у взутті
Вимірювання асиметрії й навантаження разом
Рішення про повернення до гри після травми
Раннє виявлення ризику травм Norman.ai
Контроль навантаження протягом сезону
Робота на полі, майданчику, льоду й доріжці', 'In-shoe sensor insoles
Asymmetry and load measured together
Return-to-play decisions after injury
Early injury risk detection with Norman.ai
Load management across the season
Works on court, field, ice and track', 'Тренери з фізпідготовки, медичні й наукові штаби професійних і університетських команд.', 'Strength coaches and medical and sport science staff of pro and college teams.', 'web,mobile', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
