-- Training Today — Моніторинг навантаження та відновлення
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trainingtodayapp.com' OR LOWER(`name`) = LOWER('Training Today'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Training Today', NULL, 'https://trainingtodayapp.com', NULL, NULL, 'Застосунок для Apple Watch, який стежить за даними здоров''я й показує готовність до тренувань щодня та протягом дня системою «світлофора», підказує, коли можна працювати на повну, а коли краще зменшити навантаження чи відпочити.', 'An Apple Watch app that monitors health data and shows your readiness to train each day and throughout the day with a traffic light, telling you when to go hard and when to ease off or rest.', 'Training Today постійно відстежує дані здоров''я з Apple Watch і визначає вашу готовність до тренувань щодня та протягом дня. Простий «світлофор» показує, чи готові ви працювати на повну, чи краще тренуватися легше, чи взяти день відпочинку. Це допомагає вберегтися від травм через перетренованість і обирати слушний момент для інтенсивної роботи. Застосунок цілісно дивиться на ваше життя, використовуючи можливості годинника для цілодобового моніторингу здоров''я, і перетворює ці дані на простий і зрозумілий орієнтир на шляху до тренувальної мети. Нова функція — динамічні тренувальні підходи. Розробники планують додавати функції для підготовки до конкретних стартів, наприклад першого спринт-тріатлону. Застосунок безкоштовний, а розширені графіки на iPhone доступні за разової покупки.', 'Training Today constantly monitors your health data from Apple Watch to determine your Readiness To Train each day and throughout the day. A simple traffic light shows whether you''re ready to work hard, should train lighter or take a rest day. This helps you stay safe from overtraining injury and pick the best time for intense work. The app takes a holistic view of your life, using the watch''s 24-hour health monitoring, and turns that data into a simple, accurate guide toward your training goal. A new feature is Dynamic Training Sets. The developers plan to add features for event-specific goals, such as a first sprint triathlon. The app is free, with a single in-app purchase for enhanced charts on iPhone.', 'Показник готовності до тренувань
Оцінка протягом дня
Система «світлофора»
Профілактика перетренованості
Цілодобовий моніторинг через Apple Watch
Динамічні тренувальні підходи', 'Readiness To Train score
Assessment throughout the day
Traffic light system
Overtraining prevention
24/7 monitoring via Apple Watch
Dynamic Training Sets', 'Власники Apple Watch, які регулярно тренуються й хочуть розумно дозувати навантаження.', 'Apple Watch owners who train regularly and want to manage their load wisely.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
