SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tridot.com' OR LOWER(`name`) = LOWER('TriDot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TriDot', NULL, 'https://tridot.com', NULL, NULL, 'AI-тренування для тріатлону: на основі понад 20 років даних спортсменів складає персональні тренування з плавання, велосипеда й бігу, враховує умови середовища й ваш фізіологічний профіль, щоб тренуватися менше, а виступати швидше.', 'AI triathlon training: built on more than 20 years of athlete data, it creates personal swim, bike and run workouts, accounts for your environment and physiological profile, so you train less and race faster.', 'TriDot використовує понад 20 років даних спортсменів і технологію FitLogic, щоб повністю персоналізувати тренування з плавання, велосипеда й бігу. Система переосмислює всі чотири етапи побудови програми. Оцінка визначає ваш справжній рівень у кожній дисципліні з поправкою на вік, стать, температуру, вологість і висоту над рівнем моря, тож старт відбувається з точної точки, а не з припущення. Призначення точно оцінює фізіологічне навантаження кожного заняття й підлаштовує інтенсивність під ваше реальне середовище, щоб правильне тренування було в правильний час. Далі система оцінює результати й прогнозує вашу форму. За словами компанії, такий підхід дозволяє скоротити час тренувань до 30%. Почати можна безкоштовно; є версія для тренерів, сертифікація й можливість отримати персонального тренера.', 'TriDot uses more than 20 years of athlete data and FitLogic technology to fully personalize swim, bike and run training. The system rethinks all four phases of training program design. Assessment identifies your true ability in each discipline, normalized for age, gender, temperature, humidity and elevation, so you start from an accurate baseline rather than a guess. Prescription accurately quantifies the physiological stress of each session and adjusts intensities to your actual training environment, so you get the right training at the right time. The system then evaluates results and predicts your fitness. According to the company, this approach can cut training time by up to 30%. You can start for free; there is a version for coaches, certification and the option to get a personal coach.', 'Персональні тренування з плавання, велосипеда й бігу
Оцінка реального рівня в кожній дисципліні
Поправка на вік, погоду й висоту
Оцінка навантаження кожного заняття
Прогноз форми
Версія для тренерів і сертифікація', 'Personal swim, bike and run workouts
Assessment of true ability in each discipline
Adjustments for age, weather and elevation
Training stress of every session
Fitness prediction
Coach version and certification', 'Тріатлоністи будь-якого рівня та тренери з тріатлону.', 'Triathletes of every level and triathlon coaches.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
