SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'ultrahuman.com' OR LOWER(`name`) = LOWER('Ultrahuman'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ultrahuman', NULL, 'https://ultrahuman.com', NULL, NULL, 'Екосистема для здоров''я й результатів: розумні кільця Ring AIR і Ring PRO для відстеження сну, відновлення, активності й циклу, безперервний моніторинг глюкози, розшифрування аналізів крові та монітор сну для дому.', 'An ecosystem for health and performance: Ring AIR and Ring PRO smart rings that track sleep, recovery, activity and cycles, continuous glucose monitoring, decoded blood tests and a home sleep monitor.', 'Ultrahuman — пов''язана екосистема пристроїв і сервісів для здоров''я й спортивних результатів. Розумне кільце Ring AIR відстежує сон, відновлення, метаболізм, цикл і овуляцію та при цьому значно легше за звичайний смартгодинник, а Ring PRO додає більше можливостей і потужності для активних людей. Безперервний моніторинг глюкози показує рівень цукру в реальному часі. Сервіс Blood Vision розшифровує понад 100 показників крові й перетворює їх на поради щодо способу життя та добавок. Пристрій Home — тихий монітор сну, який допомагає краще відпочивати. У Бенгалуру працює Performance Lab, де можна тренуватися, проходити тестування й відновлюватися за протоколами для довголіття й спортивних результатів. Компанія також пропонує рішення для бізнесу, розробників і креаторів.', 'Ultrahuman is a connected ecosystem of devices and services for health and athletic performance. The Ring AIR smart ring tracks sleep, recovery, metabolism, cycle and ovulation while being far lighter than a typical smartwatch, and the Ring PRO adds more intelligence and power for active people. Continuous glucose monitoring tracks blood sugar in real time. Blood Vision decodes more than 100 blood markers into lifestyle tips and supplement plans. Home is a quiet sleep monitor that helps you rest better. A Performance Lab in Bengaluru lets you train, test and recover with protocols for longevity and athletic performance. The company also offers solutions for businesses, developers and creators.', 'Розумні кільця Ring AIR і Ring PRO
Відстеження сну, відновлення й активності
Відстеження циклу й овуляції
Безперервний моніторинг глюкози
Розшифрування аналізів крові Blood Vision
Монітор сну Home', 'Ring AIR and Ring PRO smart rings
Sleep, recovery and activity tracking
Cycle and ovulation tracking
Continuous glucose monitoring
Blood Vision blood test decoding
Home sleep monitor', 'Люди, які стежать за здоров''ям, сном і відновленням, а також спортсмени.', 'People tracking their health, sleep and recovery, as well as athletes.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
