SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bolt6.ai' OR LOWER(`name`) = LOWER('Bolt6'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Bolt6', NULL, 'https://bolt6.ai', NULL, NULL, 'Технології для спорту: оптичне відстеження м''яча, гравців і навіть автомобілів у реальному часі, система суддівства Sentinel, офіційно затверджена в тенісі й волейболі, відеоповтор і графіка для трансляцій.', 'Technology for sport: real-time optical tracking of the ball, players and even cars, the Sentinel officiating system officially approved for tennis and volleyball, video replay and broadcast graphics.', 'Bolt6 з 2021 року створює технології, які покращують досвід спорту для всіх: суддівство, підготовку спортсменів, перегляд для вболівальників і комерційні результати організаторів змагань. Основа компанії — оптичне відстеження: система в реальному часі відстежує м''яч, гравців і навіть автомобілі, а її точність перевірена за допомогою технології VICON, надійність — близько 99,9%. Sentinel — система для суддівства в реальному часі, офіційно затверджена для міжнародного тенісу й волейболу та єдина затверджена хмарна технологія такого типу. Shotlink 2.0 — технологія оптичного відстеження, з якою PGA Tour по-новому збирає дані в гольфі. Окрім цього, Bolt6 пропонує системи відеоповтору й графіку для трансляцій.', 'Since 2021, Bolt6 has been building technology that improves the experience of sport for everyone: officiating, athlete performance, the fan experience and commercial results for competition organizers. Optical tracking is at the core: the system tracks the ball, players and even cars in real time, with accuracy validated using VICON technology and reliability of about 99.9%. Sentinel is a real-time officiating system officially approved for international tennis and volleyball and the only officially approved cloud-based technology of its kind. Shotlink 2.0 is the optical tracking technology behind the reimagined PGA Tour data collection. Bolt6 also offers video replay systems and broadcast graphics.', 'Оптичне відстеження м''яча й гравців
