-- LongoMatch — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'longomatch.com' OR LOWER(`name`) = LOWER('LongoMatch'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'LongoMatch', NULL, 'https://longomatch.com', NULL, NULL, 'Доступна програма відеоаналізу для тренерів у будь-якому виді спорту: розбір кожного епізоду й тактичних закономірностей, створення тренувань з реальних ігрових ситуацій, інтерактивна тактична дошка й хмарне сховище для команди.', 'Affordable video analysis software for coaches in any sport: break down every play and tactical pattern, build training from real match situations, use an interactive tactical board and cloud storage for the team.', 'LongoMatch допомагає тренерам планувати тренування, аналізувати матчі, керувати командою й ділитися матеріалами. Компанія робить професійні інструменти простими й доступними за ціною для будь-якого виду спорту й рівня — для команд із великими мріями, але невеликими бюджетами. Програма дозволяє розібрати кожен ігровий епізод і побачити закономірності, які можуть змінити гру: кожен кліп, кожна позначка й кожен висновок мають значення. Висновки легко перетворити на дії, створюючи тренування на основі реальних ситуацій з матчів. Інтерактивна тактична дошка допомагає намалювати ідеї й поділитися ними з командою. Хмарний сервіс Longocloud зберігає знання, ідеї й напрацювання команди, тож вони завжди доступні, де б ви не були.', 'LongoMatch helps coaches plan training, analyze matches, manage their team and share materials. The company makes professional tools simple and affordable for every sport and every level, for teams with big dreams but small budgets. The software lets you break down every play and reveal the patterns that change the game: every clip, every tag and every insight matters. Insights turn into action by building training sessions from real match situations. An interactive tactical board helps you draw your ideas and share them with the team. The Longocloud service stores the team''s knowledge, ideas and work so it is always available wherever you are.', 'Відеоаналіз матчів
Позначки й кліпи ігрових епізодів
Тренування на основі ігрових ситуацій
Інтерактивна тактична дошка
Хмарне сховище Longocloud
Для будь-якого виду спорту', 'Match video analysis
Tags and clips of game situations
Training built from match situations
Interactive tactical board
Longocloud cloud storage
For any sport', 'Тренери й аналітики команд будь-якого рівня й виду спорту, зокрема з невеликим бюджетом.', 'Coaches and analysts of teams of any level and sport, including those on small budgets.', 'web,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
