-- Metrica Sports — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'metrica-sports.com' OR LOWER(`name`) = LOWER('Metrica Sports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Metrica Sports', NULL, 'https://metrica-sports.com', NULL, NULL, 'Відеоаналіз для тренерів і аналітиків будь-якого рівня: простий PlayBase для аматорських і напівпрофесійних команд та Metrica Nexus для професіоналів з повним розбором гри, телестрацією, автоматичним відстеженням і аналізом наживо.', 'Video analysis for coaches and analysts at every level: the simple PlayBase for amateur and semi-pro teams and Metrica Nexus for pros, with full game analysis, telestration, automatic tracking and live analysis.', 'Metrica Sports пропонує рішення для аналізу гри як для непрофесійних, так і для професійних команд, поєднуючи відео й дані. PlayBase — інтуїтивний інструмент для аматорських і напівпрофесійних тренерів, невеликих клубів, незалежних аналітиків і звичайних користувачів, який робить оцінку виступів доступною кожному; його можна спробувати безкоштовно. Metrica Nexus розрахований на елітних аналітиків і тренерів, яким потрібні всебічні дані для покращення командної стратегії. Тарифи Nexus відрізняються можливостями: повний аналіз гри, телестрація — малювання поверх відео — і ручне відстеження на базовому рівні, автоматичне відстеження на середньому та повне відстеження кліпів на старшому. Додатковий модуль Nexus Live дозволяє аналізувати гру наживо. При оплаті за пів року чи рік діють знижки.', 'Metrica Sports offers game analysis solutions for both non-professional and professional teams, combining video and data. PlayBase is an intuitive tool for amateur and semi-professional coaches, small clubs, independent analysts and consumers that makes performance evaluation accessible to everyone; you can try it for free. Metrica Nexus is built for elite analysts and coaches who need comprehensive insights to improve team strategy. Nexus plans differ by capabilities: full game analysis, telestration (drawing over video) and manual tracking at the entry level, automatic tracking at the middle tier and full clip tracking at the top tier. The Nexus Live add-on enables live game analysis. Six-month and yearly billing come with discounts.', 'PlayBase для аматорських команд
Metrica Nexus для професіоналів
Повний аналіз гри
Телестрація — малювання поверх відео
Ручне й автоматичне відстеження
Аналіз наживо Nexus Live', 'PlayBase for amateur teams
Metrica Nexus for pros
Full game analysis
Telestration on video
Manual and automatic tracking
Nexus Live live analysis', 'Тренери й аналітики аматорських, напівпрофесійних і професійних команд, незалежні аналітики.', 'Coaches and analysts of amateur, semi-pro and pro teams, independent analysts.', 'web,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
