-- ReSpo.Vision — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'respo.vision' OR LOWER(`name`) = LOWER('ReSpo.Vision'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'ReSpo.Vision', NULL, 'https://respo.vision', NULL, NULL, 'AI і комп''ютерний зір перетворюють будь-яке відео матчу з однієї камери на дані відстеження, фізичні й тактичні показники та 3D-візуалізації — без GPS і обладнання на стадіоні. Рішення для команд, ліг, федерацій і медіа.', 'AI and computer vision turn any single-camera match video into tracking data, physical and tactical metrics and 3D visuals, with no GPS or stadium hardware. Solutions for teams, leagues, federations and media.', 'ReSpo.Vision за допомогою штучного інтелекту й комп''ютерного зору перетворює будь-яке відео матчу з однієї камери на аналітику професійного рівня, захопливі 3D-візуалізації та висновки, що приносять дохід. Команди отримують дані відстеження, фізичні показники й тактичні висновки на рівні еліти, але без великих бюджетів — лише з відео матчу, без GPS-трекерів чи іншого обладнання. Ліги й федерації можуть централізувати дані, стандартизувати аналітику й масштабувати відстеження на різні змагання, вікові групи й дивізіони, створивши єдиний центр для аналізу й звітності. Медіа й мовники додають до трансляцій графіку на полі й віртуальну рекламу без додаткових камер і датчиків. Компанія також працює з букмекерськими операторами. Технологія має сертифікат EPTS 2025.', 'ReSpo.Vision uses AI and computer vision to turn any single-camera match video into elite-level analytics, immersive 3D visuals and revenue-driving insights. Teams get performance-grade tracking, fitness data and tactical insights without elite budgets, using only match video, with no GPS or other hardware. Leagues and federations can centralize data, standardize insights and scale tracking across competitions, age groups and divisions, creating a single hub for performance, analysis and reporting. Media and broadcasters can add on-pitch overlays and virtual ads to broadcasts with no extra cameras or sensors. The company also works with sportsbooks. The technology holds 2025 EPTS certification.', 'Дані відстеження з відео однієї камери
Фізичні й тактичні показники
Без GPS і обладнання на стадіоні
3D-візуалізація матчів
Централізована аналітика для ліг
Графіка й віртуальна реклама для трансляцій', 'Tracking data from single-camera video
Physical and tactical metrics
No GPS or stadium hardware
3D match visualization
Centralized analytics for leagues
Broadcast graphics and virtual ads', 'Футбольні команди, ліги, федерації, медіа й мовники.', 'Football teams, leagues, federations, media and broadcasters.', 'web', 'course', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
