SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scoutastic.com' OR LOWER(`name`) = LOWER('SCOUTASTIC'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SCOUTASTIC', NULL, 'https://scoutastic.com', NULL, NULL, 'Платформа для планування й ведення скаутингу у футболі: скаутські звіти створюються прямо в системі й аналізуються штучним інтелектом, а ексклюзивна інтеграція з даними transfermarkt дає швидкий доступ до інформації про гравців.', 'A platform for planning and managing football scouting: scouting reports are written in the system and analyzed by AI, while an exclusive integration with transfermarkt data gives quick access to player information.', 'SCOUTASTIC — платформа для планування й керування скаутингом у футболі. Скаутські звіти створюються безпосередньо в системі, а потужний штучний інтелект аналізує їх, щоб знаходити закономірності й давати глибокі висновки. Завдяки ексклюзивному зв''язку з даними про гравців transfermarkt користувачі отримують прямий доступ до цінної інформації. Поєднання аналізу на основі AI, статистики звітів і даних transfermarkt дає обґрунтовану основу для рішень щодо відбору гравців. Інструмент цінують за гнучкість і якісну підтримку, а також за те, що всі дані зібрані в одному місці. Платформою користуються провідні клуби, зокрема в Англії й Німеччині; доступний мобільний застосунок.', 'SCOUTASTIC is a platform for planning and managing football scouting activities. Scouting reports are created directly in the system and analyzed by powerful AI to spot patterns and deliver deep insights. Through an exclusive link to transfermarkt player data, users get direct access to valuable information. Combining AI-driven analysis, report statistics and transfermarkt data provides a well-founded basis for recruitment decisions. Users value the tool''s flexibility and good support, and having all data in one place. Leading clubs, including in England and Germany, use the platform, and a mobile app is available.', 'Планування скаутингу
Скаутські звіти в платформі
AI-аналіз звітів
Інтеграція з даними transfermarkt
Статистика звітів
Мобільний застосунок', 'Scouting planning
Scouting reports in the platform
AI analysis of reports
transfermarkt data integration
Report statistics
Mobile app', 'Скаутингові відділи й керівники відбору гравців у футбольних клубах.', 'Scouting departments and heads of recruitment at football clubs.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-03 00:00:00' FROM DUAL WHERE @new = 1;
