SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'skillcorner.com' OR LOWER(`name`) = LOWER('SkillCorner'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SkillCorner', NULL, 'https://skillcorner.com', NULL, NULL, 'AI-дані відстеження для футболу, баскетболу й американського футболу: автоматично визначає положення гравців і м''яча з будь-якого одного відео, навіть з телетрансляції, для скаутингу, рекрутингу й аналізу результатів.', 'AI tracking data for football, basketball and American football: it automatically derives player and ball positions from any single video, even a TV broadcast, for scouting, recruitment and performance analysis.', 'SkillCorner — постачальник спортивних даних на основі штучного інтелекту. Компанія автоматично відстежує гравців і м''яч з будь-якого одного джерела відео — телевізійної трансляції, тактичної чи ширококутної камери — і навіть розраховує положення гравців, які опинилися поза кадром. Ці дані відстеження й AI-аналітика допомагають командам ухвалювати кращі рішення в пошуку й відборі гравців, їхньому розвитку та командній стратегії, а також у скаутингу й аналізі результатів. Рішення доступні для футболу, баскетболу й американського футболу, а окремий напрям присвячений жіночому футболу. Даними SkillCorner користуються сотні команд, ліг і федерацій по всьому світу.', 'SkillCorner is an AI-driven sports data provider. It automatically tracks players and the ball from any single camera source, broadcast, tactical or wide-angle video, and even extrapolates the positions of players who are off camera. This tracking data and AI analytics help teams make better decisions in player recruitment, development and team strategy, as well as scouting and performance analysis. Solutions cover football, basketball and American football, with dedicated work on women''s football. Hundreds of teams, leagues and federations worldwide use SkillCorner data.', 'Автоматичне відстеження гравців і м''яча
Робота з будь-яким одним відеоджерелом
