SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportlogiq.com' OR LOWER(`name`) = LOWER('Sportlogiq'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportlogiq', NULL, 'https://sportlogiq.com', NULL, NULL, 'AI-аналітика спорту: запатентовані комп''ютерний зір і машинне навчання відстежують на відео те, що не помічає людське око, і дають командам, лігам і медіа висновки, сирі дані й відеоінструменти для хокею, футболу й американського футболу.', 'AI sports analytics: patented computer vision and machine learning track what the human eye can''t see on video and give teams, leagues and media insights, raw data and video tools for hockey, soccer and American football.', 'Sportlogiq створює спортивну аналітику на основі штучного інтелекту. Запатентовані технології комп''ютерного зору й машинного навчання відстежують на відео те, що не здатне помітити людське око, і перетворюють це на дані та аналітику, які змінюють підготовку до ігор. Клієнти отримують готові висновки, сирі дані й відеоінструменти, щоб покращувати свою гру за допомогою AI. Компанія особливо сильна в аналітиці хокею, а також працює з футболом, американським футболом, дитячо-юнацьким спортом і медіа. Її послугами й даними відстеження користуються спортивні команди, ліги, медіаорганізації та компанії, що займаються підвищенням спортивних результатів у різних країнах світу. Sportlogiq нещодавно приєдналася до компанії Teamworks.', 'Sportlogiq builds AI-powered sports analytics. Its patented computer vision and machine learning technology tracks on video what the human eye cannot see and turns it into data and analytics that change game preparation. Clients get ready-made insights, raw data and video tools to enhance their game with AI. The company is especially strong in hockey analytics and also works in soccer, American football, youth sports and media. Its services and tracking data are used by sports teams, leagues, media organizations and performance companies around the world. Sportlogiq was recently acquired by Teamworks.', 'Відстеження подій на відео за допомогою AI
Готові висновки й аналітика
