SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportradar.com' OR LOWER(`name`) = LOWER('Sportradar'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportradar', NULL, 'https://sportradar.com', NULL, NULL, 'Компанія спортивних технологій: дані й API, рішення для медіа й трансляцій, тренерська й скаутингова платформа Synergy з автоматичним відео, а також послуги з чесності змагань — боротьба з договірними матчами й допінгом.', 'A sports technology company: data and APIs, media and broadcast solutions, the Synergy coaching and scouting platform with automated video, and integrity services against match-fixing and doping.', 'Sportradar — компанія спортивних технологій, яка працює на перетині спорту, медіа й ставок. Для медіа- й технологічних компаній вона надає спортивні дані через API, інструменти для створення історій і аналітику, рішення для трансляцій, редакційний контент, аудіовізуальні послуги й OTT-платформи. Командам, лігам і федераціям компанія пропонує продаж медіаправ, продакшн, маркетингові й спонсорські інструменти, а також платформу Synergy Coaching & Scouting з автоматизованим відео, тренерськими рішеннями й інструментами скаутингу. Окремий важливий напрям — чесність змагань і регулювання: моніторинг для протидії договірним матчам, антидопінгові програми, безпека в спорті та відповідність правилам. Значна частина бізнесу компанії обслуговує букмекерські й ігрові платформи.', 'Sportradar is a sports technology company at the intersection of sport, media and betting. For media and tech companies it provides sports data via API, storytelling tools and insights, broadcast solutions, editorial content, audiovisual services and OTT platforms. For teams, leagues and federations it offers media rights representation, production, marketing and sponsorship tools, and the Synergy Coaching & Scouting platform with automated video, coaching solutions and scouting tools. Another key area is integrity and regulation: monitoring to fight match-fixing, anti-doping programs, safe sport and compliance. A large part of the business serves betting and gaming platforms.', 'Спортивні дані й API
