SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hudl.com/products/sportscode' OR LOWER(`name`) = LOWER('Sportscode'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportscode', NULL, 'https://www.hudl.com/products/sportscode', NULL, NULL, 'Програма аналізу виступів для професійних команд від Hudl: повністю налаштовувані робочі процеси, зручні скрипти, швидка робота з відео й інтеграції з даними спортивної науки, зокрема з трекерами WIMU.', 'Performance analysis software for pro teams from Hudl: fully customizable workflows, better scripting, fast video handling and integrations with sports science data, including WIMU trackers.', 'Hudl Sportscode — програма аналізу виступів, якою користуються елітні спортивні команди по всьому світу. Нова версія стала потужнішою й інтуїтивнішою: кращі скрипти, швидша взаємодія й простіша інтеграція з власним робочим процесом аналітиків. Головна перевага — повністю налаштовуваний аналіз, який підлаштовується під методику конкретної команди. Sportscode поєднує можливості спортивної науки й аналізу виступів: завдяки інтеграції з трекерами WIMU можна, наприклад, побачити, коли гравці досягають максимальної швидкості або як зміна схеми гри впливає на фізичні вимоги до різних позицій. Програма доступна в кількох рівнях, а для команд доступна демонстрація. Sportscode входить до екосистеми Hudl.', 'Hudl Sportscode is performance analysis software used by elite sports teams around the world. The new version is more powerful and intuitive, with better scripting, faster interactions and easier integration with analysts'' custom workflows. Its key strength is fully customizable analysis that adapts to each team''s methodology. Sportscode combines sports science with performance analysis: with the WIMU tracker integration you can, for example, see when players reach maximum velocity or how a formation change affects the physical demands on different positions. The software comes in several tiers, and teams can request a demo. Sportscode is part of the Hudl ecosystem.', 'Повністю налаштовуваний аналіз виступів
