INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'StatMuse gives instant answers to sports statistics questions asked in plain language. Just ask, and it finds the numbers for the NBA, NFL, MLB, NHL, football, WNBA, PGA and college football. The home page features fresh stat highlights about players and games, scores, news and trending queries. A separate Money section covers financial data. Developers can use an API and MCP to connect StatMuse data and search to their own apps and AI assistants. There is also a gallery of examples, a data glossary, a blog and a mobile app. It is useful for analysts, journalists, coaches and fans who need accurate numbers without digging through tables.', 'manual' FROM DUAL WHERE @new = 1;
