SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'statsperform.com' OR LOWER(`name`) = LOWER('Stats Perform'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Stats Perform', NULL, 'https://statsperform.com', NULL, NULL, 'Компанія спортивних даних і AI, відома даними Opta: потоки даних наживо, AI-інструменти для медіа, аналітичні рішення Opta Pro для команд, ліг і федерацій, графіка, відео й контент для трансляцій та вболівальників.', 'A sports data and AI company known for Opta data: live data feeds, AI tools for media, Opta Pro analytics for teams, leagues and federations, graphics, video and content for broadcasts and fans.', 'Stats Perform — компанія спортивних даних і штучного інтелекту, відома брендом Opta. Вона збирає детальні дані про спортивні події й перетворює їх на продукти для різних аудиторій. Командам, лігам і федераціям компанія допомагає покращувати результати й залучати аудиторію: зокрема, через рішення Opta Pro Hub і Opta ProVision для аналізу виступів. Медіа й творцям контенту Stats Perform дає швидші історії й цікавіший контент, мовникам і стрімінговим сервісам — дані наживо, AI-інструменти й аналітику для глибших трансляцій. Серед продуктів — потоки даних Opta, Opta Vision, OptaAI Studio, пошук Opta Search, графіка, редакційні рішення, новини й відео, API статистики та рішення для залучення вболівальників. Окремий напрям компанії обслуговує букмекерські компанії.', 'Stats Perform is a sports data and AI company known for the Opta brand. It collects detailed data about sporting events and turns it into products for different audiences. For teams, leagues and federations it supports better performance and audience engagement, including through Opta Pro Hub and Opta ProVision for performance analysis. Media and creators get faster storytelling and richer content, while broadcasters and streamers get live data, AI tools and analysis for deeper coverage. Products include Opta data feeds, Opta Vision, OptaAI Studio, Opta Search, graphics, editorial solutions, news and video, a stats API and fan engagement solutions. A separate part of the business serves sportsbooks.', 'Детальні спортивні дані Opta
